-- Academy-inhoud: volledige NL/FR/EN-pool met leeftijdssporen en drie 16+-rondes.
-- Herhaalbaar; certificaten en resultaten worden niet gewijzigd.
BEGIN;
DELETE FROM academy_vragen WHERE academy_id IN (SELECT id FROM academies WHERE is_active);

-- appartementskat: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'appartementskat' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Waarom is verticale ruimte belangrijk voor een appartementskat?','Pourquoi l''espace vertical est-il important pour un chat d''appartement ?','Why is vertical space important for an apartment cat?','["Katten houden niet van hoogte", "Het geeft extra territorium en uitkijkpunten in een beperkte ruimte", "Het is enkel decoratief", "Het is gevaarlijk voor katten"]'::jsonb,'["Les chats n''aiment pas la hauteur", "Cela offre plus de territoire et des points d''observation dans un espace limité", "C''est purement décoratif", "C''est dangereux pour les chats"]'::jsonb,'["Cats dislike height", "It provides extra territory and vantage points in a limited space", "It''s purely decorative", "It''s dangerous for cats"]'::jsonb,1,'Kattenrekken en hoge plekken vergroten het bruikbare territorium in een klein appartement en verminderen stress.','Les arbres à chat et les hauteurs augmentent le territoire utile dans un petit appartement et réduisent le stress.','Cat trees and high perches expand usable territory in a small apartment and reduce stress.'),
  (1,'tekst','Hoeveel kattenbakken worden aanbevolen voor één kat in een appartement?','Combien de bacs à litière sont recommandés pour un chat en appartement ?','How many litter boxes are recommended for one cat in an apartment?','["0, buiten volstaat", "Minstens 2 (aantal katten + 1)", "Enkel 1 is altijd genoeg", "5 of meer, altijd"]'::jsonb,'["0, l''extérieur suffit", "Au moins 2 (nombre de chats + 1)", "1 seul suffit toujours", "5 ou plus, systématiquement"]'::jsonb,'["0, outside is enough", "At least 2 (number of cats + 1)", "Just 1 is always enough", "5 or more, always"]'::jsonb,1,'De vuistregel is aantal katten plus één bak, verspreid op verschillende plekken, om conflicten en vervuiling te vermijden.','La règle est nombre de chats plus un bac, répartis à différents endroits, pour éviter conflits et saleté.','The rule of thumb is number of cats plus one box, spread around, to avoid conflict and mess.'),
  (1,'tekst','Wat is een belangrijk gevaar voor katten in appartementen op hogere verdiepingen?','Quel est un danger important pour les chats dans les appartements en étage ?','What is an important danger for cats in apartments on higher floors?','["Vallen door onbeveiligde ramen (high-rise syndroom)", "Te veel zonlicht", "Te weinig geluid", "Te koude vloeren"]'::jsonb,'["Chute par des fenêtres non sécurisées (syndrome du gratte-ciel)", "Trop de lumière du soleil", "Trop peu de bruit", "Sols trop froids"]'::jsonb,'["Falling through unsecured windows (high-rise syndrome)", "Too much sunlight", "Too little noise", "Cold floors"]'::jsonb,0,'Katten kunnen door open ramen vallen bij het jagen op vogels of insecten; horren zijn essentieel.','Les chats peuvent tomber par des fenêtres ouvertes en chassant oiseaux ou insectes ; des moustiquaires sont essentielles.','Cats can fall through open windows while chasing birds or insects; screens are essential.'),
  (1,'tekst','Waarom is krabmateriaal essentieel in een appartement zonder buitenruimte?','Pourquoi le matériel à griffer est-il essentiel dans un appartement sans espace extérieur ?','Why is scratching material essential in an apartment without outdoor access?','["Om het meubilair te sparen en natuurlijk gedrag te uiten", "Enkel om nagels te verwijderen", "Het is niet nodig binnenshuis", "Om de kat te straffen"]'::jsonb,'["Pour préserver les meubles et exprimer un comportement naturel", "Uniquement pour enlever les griffes", "Ce n''est pas nécessaire en intérieur", "Pour punir le chat"]'::jsonb,'["To spare furniture and express natural behaviour", "Only to remove nails", "It''s not needed indoors", "To punish the cat"]'::jsonb,0,'Krabben is een natuurlijke behoefte om klauwen te onderhouden en territorium te markeren.','Griffer est un besoin naturel pour entretenir les griffes et marquer le territoire.','Scratching is a natural need to maintain claws and mark territory.'),
  (2,'tekst','Hoe vaak per dag eet een volwassen kat idealiter?','Combien de fois par jour un chat adulte doit-il idéalement manger ?','How many times a day should an adult cat ideally eat?','["1 grote maaltijd", "2-4 kleinere maaltijden", "Continu onbeperkt droogvoer zonder controle", "Om de twee dagen"]'::jsonb,'["1 gros repas", "2 à 4 petits repas", "Croquettes en libre-service constant sans contrôle", "Tous les deux jours"]'::jsonb,'["1 large meal", "2-4 smaller meals", "Constant unlimited dry food with no control", "Every other day"]'::jsonb,1,'Meerdere kleine maaltijden bootsen het natuurlijke jachtpatroon van katten na en helpen overgewicht voorkomen.','Plusieurs petits repas imitent le schéma de chasse naturel du chat et aident à prévenir le surpoids.','Multiple small meals mimic a cat''s natural hunting pattern and help prevent obesity.'),
  (2,'tekst','Wat is een risico van een te sedentaire levensstijl bij een binnenkat?','Quel est un risque d''un mode de vie trop sédentaire chez un chat d''intérieur ?','What is a risk of a too sedentary lifestyle for an indoor cat?','["Betere spijsvertering", "Overgewicht en gewrichtsproblemen", "Langer leven zonder gevolgen", "Meer energie"]'::jsonb,'["Meilleure digestion", "Surpoids et problèmes articulaires", "Vie plus longue sans conséquences", "Plus d''énergie"]'::jsonb,'["Better digestion", "Obesity and joint problems", "Longer life with no consequences", "More energy"]'::jsonb,1,'Weinig beweging binnenshuis kan leiden tot overgewicht, wat gewrichten en algemene gezondheid belast.','Le manque d''exercice en intérieur peut mener au surpoids, ce qui pèse sur les articulations et la santé générale.','Little indoor exercise can lead to obesity, straining joints and overall health.'),
  (2,'tekst','Welk voedsel is giftig voor katten?','Quel aliment est toxique pour les chats ?','Which food is toxic to cats?','["Gekookte kip", "Ui en look", "Kattengras", "Gestoomde vis zonder graten"]'::jsonb,'["Poulet cuit", "Oignon et ail", "Herbe à chat", "Poisson vapeur sans arêtes"]'::jsonb,'["Cooked chicken", "Onion and garlic", "Cat grass", "Steamed fish without bones"]'::jsonb,1,'Ui en look bevatten stoffen die rode bloedcellen bij katten kunnen beschadigen en bloedarmoede veroorzaken.','L''oignon et l''ail contiennent des substances pouvant endommager les globules rouges des chats et causer de l''anémie.','Onion and garlic contain substances that can damage cats'' red blood cells and cause anaemia.'),
  (2,'tekst','Wat kan wijzen op stress of ziekte bij een binnenkat?','Qu''est-ce qui peut indiquer du stress ou une maladie chez un chat d''intérieur ?','What can indicate stress or illness in an indoor cat?','["Normaal speelgedrag", "Buiten de kattenbak plassen of overmatig poetsen", "Regelmatig eten", "Rustig slapen"]'::jsonb,'["Comportement de jeu normal", "Uriner hors du bac ou toilettage excessif", "Manger régulièrement", "Dormir calmement"]'::jsonb,'["Normal play behaviour", "Urinating outside the litter box or excessive grooming", "Eating regularly", "Sleeping calmly"]'::jsonb,1,'Onzindelijkheid en overmatig poetsen zijn vaak signalen van stress, verveling of onderliggende gezondheidsproblemen.','Malpropreté et toilettage excessif sont souvent des signaux de stress, d''ennui ou de problèmes de santé sous-jacents.','House-soiling and excessive grooming are often signals of stress, boredom, or underlying health issues.'),
  (3,'tekst','Hoe kan je natuurlijk jaaggedrag stimuleren bij een appartementskat?','Comment stimuler le comportement de chasse naturel chez un chat d''appartement ?','How can you stimulate natural hunting behaviour in an apartment cat?','["Met interactief speelgoed zoals hengels en puzzelvoeders", "Door de kat de hele dag te laten slapen", "Door nooit te spelen", "Door enkel droogvoer in een bak te geven"]'::jsonb,'["Avec des jouets interactifs comme cannes à pêche et distributeurs à énigmes", "En laissant le chat dormir toute la journée", "En ne jouant jamais", "En donnant uniquement des croquettes dans un bol"]'::jsonb,'["With interactive toys like wand toys and puzzle feeders", "By letting the cat sleep all day", "By never playing", "By only giving dry food in a bowl"]'::jsonb,0,'Interactief spel en puzzelvoeders bootsen jachtgedrag na en houden een binnenkat mentaal gestimuleerd.','Le jeu interactif et les distributeurs à énigmes imitent le comportement de chasse et stimulent mentalement le chat d''intérieur.','Interactive play and puzzle feeders mimic hunting behaviour and keep an indoor cat mentally stimulated.'),
  (3,'tekst','Waarom is een vaste, voorspelbare routine belangrijk voor een appartementskat?','Pourquoi une routine fixe et prévisible est-elle importante pour un chat d''appartement ?','Why is a fixed, predictable routine important for an apartment cat?','["Het vermindert stress door voorspelbaarheid van voeding en spel", "Katten hebben geen routine nodig", "Het maakt geen verschil voor katten", "Enkel belangrijk voor kittens"]'::jsonb,'["Cela réduit le stress grâce à la prévisibilité des repas et du jeu", "Les chats n''ont pas besoin de routine", "Cela ne change rien pour les chats", "Important uniquement pour les chatons"]'::jsonb,'["It reduces stress through predictability of feeding and play", "Cats don''t need routine", "It makes no difference for cats", "Only important for kittens"]'::jsonb,0,'Katten zijn gevoelig voor verandering; een vaste routine van eten en spelen geeft veiligheid en rust.','Les chats sont sensibles au changement ; une routine fixe de repas et de jeu apporte sécurité et calme.','Cats are sensitive to change; a fixed routine of feeding and play provides security and calm.'),
  (3,'tekst','Hoe reageer je het best als je kat verstopt zit tijdens een verhuis of drukte?','Comment réagir au mieux si votre chat se cache pendant un déménagement ou une agitation ?','How should you best react if your cat hides during a move or busy period?','["De kat forceren om te voorschijn te komen", "Rust en tijd geven, met toegang tot een veilige plek", "De kat straffen", "De kat negeren volledig zonder controle"]'::jsonb,'["Forcer le chat à sortir", "Lui laisser calme et temps, avec accès à un endroit sûr", "Punir le chat", "L''ignorer complètement sans surveillance"]'::jsonb,'["Force the cat to come out", "Give calm and time, with access to a safe spot", "Punish the cat", "Ignore it entirely with no check-ins"]'::jsonb,1,'Katten hebben nood aan een veilige schuilplaats om stress te verwerken; geduld herstelt vertrouwen sneller.','Les chats ont besoin d''une cachette sûre pour gérer le stress ; la patience restaure la confiance plus vite.','Cats need a safe hiding spot to process stress; patience restores trust faster.'),
  (3,'tekst','Waarom is het aanbieden van meerdere rustplekken belangrijk in een appartement met meerdere katten?','Pourquoi est-il important d''offrir plusieurs lieux de repos dans un appartement avec plusieurs chats ?','Why is offering multiple resting spots important in an apartment with multiple cats?','["Om conflicten en concurrentie om ruimte te verminderen", "Katten delen graag altijd dezelfde plek", "Het heeft geen invloed op hun gedrag", "Om de kat te straffen"]'::jsonb,'["Pour réduire les conflits et la compétition pour l''espace", "Les chats aiment toujours partager le même endroit", "Cela n''a aucune influence sur leur comportement", "Pour punir le chat"]'::jsonb,'["To reduce conflict and competition for space", "Cats always love sharing the same spot", "It has no effect on their behaviour", "To punish the cat"]'::jsonb,0,'Elke kat heeft eigen territorium nodig; voldoende rustplekken vermijden spanning tussen kattenn in huis.','Chaque chat a besoin de son propre territoire ; suffisamment de lieux de repos évitent les tensions entre chats.','Each cat needs its own territory; enough resting spots avoid tension between cats in the home.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- axolotl: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'axolotl' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Welke watertemperatuur is ideaal voor een axolotl?','Quelle température de l''eau est idéale pour un axolotl ?','What water temperature is ideal for an axolotl?','["Ongeveer 16-18°C","Ongeveer 28-30°C","Ongeveer 5°C","Temperatuur maakt niet uit"]'::jsonb,'["Environ 16-18°C","Environ 28-30°C","Environ 5°C","La température n''a pas d''importance"]'::jsonb,'["About 16-18°C","About 28-30°C","About 5°C","Temperature doesn''t matter"]'::jsonb,0,'Axolotls komen uit koele bergmeren in Mexico en lijden onder warm water, dat hun stofwisseling en immuunsysteem verstoort.','Les axolotls viennent de lacs de montagne froids au Mexique et souffrent dans une eau chaude.','Axolotls come from cool mountain lakes in Mexico and suffer in warm water, which stresses their metabolism.'),
(1,'tekst','Waarom is een filter met zachte, langzame stroming belangrijk in een axolotlaquarium?','Pourquoi un filtre à courant doux et lent est-il important dans un aquarium à axolotl ?','Why is a filter with a gentle, slow flow important in an axolotl tank?','["Sterke stroming stresst axolotls en bemoeilijkt zwemmen","Axolotls houden juist van sterke stroming","Filters zijn niet nodig voor axolotls","Stroming heeft geen effect op axolotls"]'::jsonb,'["Un fort courant stresse les axolotls et gêne leur nage","Les axolotls adorent au contraire un fort courant","Les filtres ne sont pas nécessaires pour les axolotls","Le courant n''a aucun effet sur les axolotls"]'::jsonb,'["Strong flow stresses axolotls and makes swimming difficult","Axolotls actually love strong currents","Filters aren''t needed for axolotls","Flow has no effect on axolotls"]'::jsonb,0,'Axolotls leven van nature in rustig water en hebben moeite met sterke stromingen die energie kosten.','Les axolotls vivent naturellement en eau calme et ont du mal avec les forts courants.','Axolotls naturally live in calm water and struggle with strong currents that cost them energy.'),
(1,'tekst','Wat is een geschikte bodembedekking voor een axolotlaquarium?','Quel substrat convient pour un aquarium à axolotl ?','What is a suitable substrate for an axolotl tank?','["Fijn zand of een kale bodem","Grof grind dat ingeslikt kan worden","Scherpe stenen","Er is geen bodembedekking nodig noch geschikt"]'::jsonb,'["Du sable fin ou un fond nu","Du gravier grossier qui peut être avalé","Des pierres tranchantes","Aucun substrat n''est nécessaire ni adapté"]'::jsonb,'["Fine sand or a bare bottom","Coarse gravel that can be swallowed","Sharp stones","No substrate is needed or suitable"]'::jsonb,0,'Grof grind kan door axolotls worden ingeslikd tijdens het jagen en darmverstopping veroorzaken.','Le gravier grossier peut être avalé par les axolotls en chassant et provoquer une occlusion intestinale.','Coarse gravel can be swallowed by axolotls while hunting and cause intestinal blockage.'),
(1,'tekst','Waarom hebben axolotls geen UVB-lamp of basking-plek nodig, in tegenstelling tot veel reptielen?','Pourquoi les axolotls n''ont-ils pas besoin de lampe UVB ni de zone de bain, contrairement à beaucoup de reptiles ?','Why don''t axolotls need a UVB lamp or basking spot, unlike many reptiles?','["Ze zijn volledig aquatisch en verlaten het water nooit","Ze zijn eigenlijk reptielen die zonlicht nodig hebben","UVB is toch nodig, dit is een foute veronderstelling","Axolotls hebben net een sterkere UVB nodig dan reptielen"]'::jsonb,'["Ils sont entièrement aquatiques et ne quittent jamais l''eau","Ce sont en fait des reptiles qui ont besoin de soleil","L''UVB est quand même nécessaire","Les axolotls ont besoin d''un UVB encore plus fort que les reptiles"]'::jsonb,'["They are fully aquatic and never leave the water","They are actually reptiles that need sunlight","UVB is needed after all, this is a wrong assumption","Axolotls need even stronger UVB than reptiles"]'::jsonb,0,'Axolotls zijn amfibieën die hun hele leven in het water blijven en dus geen basking-gedrag vertonen zoals reptielen.','Les axolotls sont des amphibiens qui restent toute leur vie dans l''eau et n''ont donc pas besoin de bain de soleil.','Axolotls are amphibians that stay in water their whole life and therefore don''t bask like reptiles.'),
(2,'tekst','Wat eten axolotls voornamelijk?','Que mangent principalement les axolotls ?','What do axolotls mainly eat?','["Wormen, kleine kreeftjes en speciale korrels","Groenten en fruit","Enkel plantaardig materiaal","Brood en graanproducten"]'::jsonb,'["Des vers, petites crevettes et granulés spécifiques","Des légumes et des fruits","Uniquement des matières végétales","Du pain et des céréales"]'::jsonb,'["Worms, small crustaceans and specialised pellets","Vegetables and fruit","Only plant material","Bread and grain products"]'::jsonb,0,'Axolotls zijn vleeseters en jagen met hun uitstekende reukzin naar kleine waterdieren.','Les axolotls sont carnivores et chassent de petits animaux aquatiques grâce à leur excellent odorat.','Axolotls are carnivores and hunt small aquatic prey using their excellent sense of smell.'),
(2,'tekst','Waarom is een goede waterkwaliteit cruciaal voor de gezondheid van een axolotl?','Pourquoi une bonne qualité de l''eau est-elle cruciale pour la santé d''un axolotl ?','Why is good water quality crucial for an axolotl''s health?','["Axolotls ademen via kieuwen en huid, gevoelig voor vervuild water","Axolotls ademen enkel lucht dus water speelt geen rol","Waterkwaliteit heeft geen invloed op amfibieën","Axolotls filteren zelf hun water perfect"]'::jsonb,'["Les axolotls respirent par branchies et peau, sensibles à l''eau polluée","Les axolotls ne respirent que de l''air donc l''eau importe peu","La qualité de l''eau n''a aucun effet sur les amphibiens","Les axolotls filtrent parfaitement leur eau eux-mêmes"]'::jsonb,'["Axolotls breathe through gills and skin, sensitive to dirty water","Axolotls only breathe air so water quality doesn''t matter","Water quality has no effect on amphibians","Axolotls filter their own water perfectly"]'::jsonb,0,'Vervuild water met ammoniak of nitriet kan via de gevoelige huid en kieuwen snel schade toebrengen.','Une eau polluée par l''ammoniac ou les nitrites peut rapidement nuire via la peau sensible et les branchies.','Polluted water with ammonia or nitrite can quickly cause harm via the sensitive skin and gills.'),
(2,'tekst','Wat is een teken van stress of ziekte bij een axolotl?','Quel est un signe de stress ou de maladie chez un axolotl ?','What is a sign of stress or illness in an axolotl?','["Gekrompen of beschadigde kieuwen","Grote, pluizige kieuwen","Actief zwemmen na het voeren","Rustig op de bodem liggen"]'::jsonb,'["Des branchies rétrécies ou abîmées","De grandes branchies touffues","Nager activement après avoir mangé","Se reposer calmement au fond"]'::jsonb,'["Shrunken or damaged gills","Large, fluffy gills","Swimming actively after feeding","Resting calmly on the bottom"]'::jsonb,0,'Gezonde kieuwen zijn vol en pluizig; gekrompen kieuwen wijzen vaak op slechte waterkwaliteit of stress.','Des branchies saines sont pleines et touffues ; des branchies rétrécies indiquent souvent une mauvaise qualité de l''eau.','Healthy gills are full and fluffy; shrunken gills often indicate poor water quality or stress.'),
(2,'tekst','Hoe vaak moet je een volwassen axolotl voeren?','À quelle fréquence faut-il nourrir un axolotl adulte ?','How often should you feed an adult axolotl?','["Ongeveer om de 2-3 dagen","Meerdere keren per dag","Eén keer per maand","Nooit, ze eten van nature niets"]'::jsonb,'["Environ tous les 2-3 jours","Plusieurs fois par jour","Une fois par mois","Jamais, ils ne mangent naturellement rien"]'::jsonb,'["About every 2-3 days","Several times a day","Once a month","Never, they naturally eat nothing"]'::jsonb,0,'Te vaak voeren kan de waterkwaliteit snel verslechteren en obesitas veroorzaken bij axolotls.','Nourrir trop souvent peut rapidement dégrader la qualité de l''eau et causer l''obésité chez les axolotls.','Feeding too often can quickly worsen water quality and cause obesity in axolotls.'),
(3,'tekst','Waarom moet je een axolotl zo weinig mogelijk uit het water hanteren?','Pourquoi faut-il manipuler un axolotl le moins possible hors de l''eau ?','Why should you handle an axolotl out of water as little as possible?','["Hun huid is zeer gevoelig en droogt snel uit","Axolotls kunnen makkelijk een tijdje op het droge leven","Handling buiten water versterkt hun kieuwen","Het heeft geen enkel effect op hun welzijn"]'::jsonb,'["Leur peau est très sensible et sèche rapidement","Les axolotls peuvent facilement vivre un moment hors de l''eau","La manipulation hors de l''eau renforce leurs branchies","Cela n''a aucun effet sur leur bien-être"]'::jsonb,'["Their skin is very sensitive and dries out quickly","Axolotls can easily live out of water for a while","Handling out of water strengthens their gills","It has no effect on their wellbeing at all"]'::jsonb,0,'De huid van axolotls heeft geen beschermende schubben en is erg gevoelig voor uitdroging en beschadiging.','La peau des axolotls n''a pas d''écailles protectrices et est très sensible au dessèchement et aux blessures.','Axolotl skin has no protective scales and is very sensitive to drying out and injury.'),
(3,'tekst','Wat moet je vermijden bij het optillen van een axolotl indien echt nodig?','Que faut-il éviter en soulevant un axolotl si c''est vraiment nécessaire ?','What should you avoid when lifting an axolotl if truly necessary?','["Het vastpakken met droge handen of een net met scherpe randen","Het gebruik van een natte kom of bakje","Het ondersteunen van het volledige lichaam","Het kort uit het water halen"]'::jsonb,'["Le saisir avec des mains sèches ou un filet aux bords tranchants","Utiliser un bol ou récipient humide","Soutenir tout le corps","Le sortir brièvement de l''eau"]'::jsonb,'["Grabbing it with dry hands or a net with sharp edges","Using a wet bowl or container","Supporting the whole body","Briefly taking it out of the water"]'::jsonb,0,'Droge handen en netten kunnen de gevoelige huid en kieuwen van een axolotl beschadigen.','Des mains sèches et des filets peuvent endommager la peau sensible et les branchies d''un axolotl.','Dry hands and nets can damage an axolotl''s sensitive skin and gills.'),
(3,'tekst','Wat betekent het als een axolotl zijn kieuwen platlegt tegen het lichaam?','Que signifie le fait qu''un axolotl plaque ses branchies contre son corps ?','What does it mean when an axolotl flattens its gills against its body?','["Mogelijk stress of slechte waterkwaliteit","Het dier is aan het spelen","Het is een teken van honger","Het betekent dat het dier gaat groeien"]'::jsonb,'["Un possible stress ou une mauvaise qualité de l''eau","L''animal est en train de jouer","C''est un signe de faim","Cela signifie que l''animal va grandir"]'::jsonb,'["Possible stress or poor water quality","The animal is playing","It is a sign of hunger","It means the animal is about to grow"]'::jsonb,0,'Platliggende kieuwen kunnen wijzen op ongemak, stress of een probleem met de waterparameters.','Des branchies aplaties peuvent indiquer un inconfort, du stress ou un problème de paramètres de l''eau.','Flattened gills can indicate discomfort, stress, or a problem with water parameters.'),
(3,'tekst','Waarom is rustig, minimaal contact belangrijk voor axolotls op een kinderboerderij?','Pourquoi un contact calme et minimal est-il important pour les axolotls dans une ferme pédagogique ?','Why is calm, minimal contact important for axolotls at a city farm?','["Ze zijn gevoelige dieren die snel gestrest raken door aanraking","Axolotls genieten juist van veel fysiek contact","Contact heeft geen invloed op axolotls","Ze moeten net vaak gestreeld worden voor hun gezondheid"]'::jsonb,'["Ce sont des animaux sensibles qui stressent vite au contact","Les axolotls adorent au contraire beaucoup de contact physique","Le contact n''a aucune influence sur les axolotls","Ils doivent au contraire être souvent caressés pour leur santé"]'::jsonb,'["They are sensitive animals that stress easily from touch","Axolotls actually enjoy lots of physical contact","Contact has no effect on axolotls at all","They actually need frequent petting for their health"]'::jsonb,0,'Axolotls zijn niet gewend aan handling en fysiek contact kan hun kwetsbare huid en welzijn schaden.','Les axolotls ne sont pas habitués à être manipulés et le contact physique peut nuire à leur peau fragile.','Axolotls aren''t used to handling, and physical contact can harm their fragile skin and wellbeing.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- baardagame: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'baardagame' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Waarom heeft een baardagame UVB-licht nodig?','Pourquoi un dragon barbu a-t-il besoin de lumière UVB ?','Why does a bearded dragon need UVB light?','["Om vitamine D3 aan te maken voor calciumopname","Om beter te kunnen zien in het donker","Om een mooiere kleur te krijgen","UVB is niet nodig binnenshuis"]'::jsonb,'["Pour produire de la vitamine D3 et absorber le calcium","Pour mieux voir dans le noir","Pour avoir une plus belle couleur","L''UVB n''est pas nécessaire en intérieur"]'::jsonb,'["To produce vitamin D3 for calcium absorption","To see better in the dark","To get a nicer colour","UVB isn''t needed indoors"]'::jsonb,0,'Zonder UVB kan een baardagame geen vitamine D3 aanmaken en geen calcium goed opnemen, wat botproblemen veroorzaakt.','Sans UVB, un dragon barbu ne peut pas produire de vitamine D3 ni absorber le calcium, causant des problèmes osseux.','Without UVB, a bearded dragon cannot produce vitamin D3 or absorb calcium properly, causing bone disease.'),
(1,'tekst','Wat is een geschikte basking-temperatuur voor een baardagame?','Quelle est une température de zone de chauffe adaptée pour un dragon barbu ?','What is a suitable basking temperature for a bearded dragon?','["Ongeveer 38-42°C","Ongeveer 15°C","Ongeveer 60°C","Kamertemperatuur is voldoende"]'::jsonb,'["Environ 38-42°C","Environ 15°C","Environ 60°C","La température ambiante suffit"]'::jsonb,'["About 38-42°C","About 15°C","About 60°C","Room temperature is enough"]'::jsonb,0,'Baardagamen komen uit warme, droge streken van Australië en hebben hoge temperaturen nodig om te verteren.','Les dragons barbus viennent des régions chaudes et sèches d''Australie et ont besoin de hautes températures pour digérer.','Bearded dragons come from hot, dry Australian regions and need high temperatures to digest food.'),
(1,'tekst','Welke bodembedekking is aan te raden voor jonge baardagamen?','Quel substrat est recommandé pour les jeunes dragons barbus ?','What substrate is recommended for young bearded dragons?','["Een vast, niet-inslikbaar oppervlak zoals tegel of krant","Los zand dat makkelijk ingeslikt wordt","Fijne houtsnippers die stof veroorzaken","Geen bodembedekking is nodig noch aan te raden om te vermijden"]'::jsonb,'["Une surface solide et non ingérable comme du carrelage ou du papier","Du sable fin facilement ingéré","Des copeaux de bois fins qui font de la poussière","Aucun substrat n''est nécessaire"]'::jsonb,'["A solid, non-ingestible surface like tile or paper","Loose sand that is easily swallowed","Fine wood shavings that create dust","No substrate is needed at all"]'::jsonb,0,'Jonge baardagamen kunnen zand inslikken bij het jagen op voedsel, wat darmverstopping kan veroorzaken.','Les jeunes dragons barbus peuvent avaler du sable en chassant leur nourriture, ce qui peut causer une occlusion.','Young bearded dragons can swallow sand while hunting food, which can cause impaction.'),
(1,'tekst','Hoe groot moet het terrarium minstens zijn voor een volwassen baardagame?','Quelle taille minimale doit avoir le terrarium pour un dragon barbu adulte ?','How big should the enclosure be at minimum for an adult bearded dragon?','["Minstens 120x60x60 cm","Een kleine plastic bak van 30 cm volstaat","Ze hebben geen vast terrarium nodig","Een aquarium van 20 liter is genoeg"]'::jsonb,'["Au moins 120x60x60 cm","Un petit bac en plastique de 30 cm suffit","Ils n''ont pas besoin de terrarium fixe","Un aquarium de 20 litres suffit"]'::jsonb,'["At least 120x60x60 cm","A small 30cm plastic tub is enough","They don''t need a fixed enclosure","A 20-litre tank is enough"]'::jsonb,0,'Volwassen baardagamen worden vrij groot en hebben ruimte nodig voor een goede thermische gradiënt.','Les dragons barbus adultes deviennent assez grands et ont besoin d''espace pour un bon gradient thermique.','Adult bearded dragons grow quite large and need space for a proper thermal gradient.'),
(2,'tekst','Wat eet een baardagame in het wild en in gevangenschap?','Que mange un dragon barbu dans la nature et en captivité ?','What does a bearded dragon eat in the wild and in captivity?','["Een mix van insecten en groenten","Enkel vlees","Enkel fruit","Uitsluitend melkproducten"]'::jsonb,'["Un mélange d''insectes et de légumes","Uniquement de la viande","Uniquement des fruits","Uniquement des produits laitiers"]'::jsonb,'["A mix of insects and vegetables","Only meat","Only fruit","Only dairy products"]'::jsonb,0,'Baardagamen zijn omnivoren: jonge dieren eten meer insecten, volwassenen meer groenten.','Les dragons barbus sont omnivores : les jeunes mangent plus d''insectes, les adultes plus de légumes.','Bearded dragons are omnivores: young ones eat more insects, adults eat more vegetables.'),
(2,'tekst','Waarom moet voer bestrooid worden met calciumpoeder?','Pourquoi la nourriture doit-elle être saupoudrée de poudre de calcium ?','Why should food be dusted with calcium powder?','["Om metabole botziekte te voorkomen","Om het voer lekkerder te maken","Het is niet nodig als er UVB is","Om de kleur van het voer te verbeteren"]'::jsonb,'["Pour prévenir la maladie osseuse métabolique","Pour rendre la nourriture plus savoureuse","Ce n''est pas nécessaire s''il y a de l''UVB","Pour améliorer la couleur de la nourriture"]'::jsonb,'["To prevent metabolic bone disease","To make the food taste better","It''s not needed if there''s UVB","To improve the colour of the food"]'::jsonb,0,'Extra calcium is nodig naast UVB om voldoende opname te garanderen en botproblemen te voorkomen.','Un apport supplémentaire de calcium est nécessaire en plus de l''UVB pour garantir une bonne absorption.','Extra calcium is needed alongside UVB to ensure proper absorption and prevent bone problems.'),
(2,'tekst','Wat kan een teken zijn van metabole botziekte bij een baardagame?','Quel peut être un signe de maladie osseuse métabolique chez un dragon barbu ?','What can be a sign of metabolic bone disease in a bearded dragon?','["Zwakke of gebogen ledematen","Een extra lange staart","Een groter dan normaal hongergevoel","Snellere groei dan normaal"]'::jsonb,'["Des membres faibles ou tordus","Une queue anormalement longue","Un appétit plus grand que la normale","Une croissance plus rapide que la normale"]'::jsonb,'["Weak or bent limbs","An unusually long tail","A bigger-than-normal appetite","Faster growth than normal"]'::jsonb,0,'Een tekort aan calcium en UVB kan leiden tot zachte, misvormde botten en zwakte.','Un manque de calcium et d''UVB peut entraîner des os mous, déformés et une faiblesse générale.','A lack of calcium and UVB can lead to soft, deformed bones and weakness.'),
(2,'tekst','Hoe vaak moet je vers water en voer verversen voor een baardagame?','À quelle fréquence faut-il renouveler l''eau et la nourriture fraîches d''un dragon barbu ?','How often should fresh water and food be refreshed for a bearded dragon?','["Dagelijks","Eén keer per maand","Enkel bij ziekte","Nooit nodig, ze drinken niet"]'::jsonb,'["Quotidiennement","Une fois par mois","Uniquement en cas de maladie","Jamais nécessaire, ils ne boivent pas"]'::jsonb,'["Daily","Once a month","Only when sick","Never needed, they don''t drink"]'::jsonb,0,'Dagelijks vers water en voer voorkomt bacteriegroei en houdt de baardagame gezond.','De l''eau et de la nourriture fraîches chaque jour préviennent la prolifération bactérienne.','Fresh water and food daily prevents bacterial growth and keeps the dragon healthy.'),
(3,'tekst','Wat betekent het als een baardagame zwaait met een voorpoot?','Que signifie le fait qu''un dragon barbu agite une patte avant ?','What does it mean when a bearded dragon waves a front leg?','["Een onderdanig of sociaal signaal","Een teken van agressie","Ze proberen te vliegen","Het betekent dat ze honger hebben"]'::jsonb,'["Un signal de soumission ou social","Un signe d''agressivité","Elles essaient de voler","Cela signifie qu''elles ont faim"]'::jsonb,'["A submissive or social signal","A sign of aggression","They are trying to fly","It means they are hungry"]'::jsonb,0,'Armzwaaien is een natuurlijk sociaal gedrag waarmee baardagamen communiceren zonder confrontatie.','Le fait d''agiter le bras est un comportement social naturel utilisé pour communiquer sans confrontation.','Arm-waving is a natural social behaviour bearded dragons use to communicate without confrontation.'),
(3,'tekst','Wat betekent een zwarte baard bij een baardagame meestal?','Que signifie généralement une barbe noire chez un dragon barbu ?','What does a black beard usually mean in a bearded dragon?','["Stress, dreiging of opwinding","Dat het dier honger heeft","Dat het dier gaat vervellen","Dat het dier ziek is van kou"]'::jsonb,'["Du stress, une menace ou de l''excitation","Que l''animal a faim","Que l''animal va muer","Que l''animal est malade à cause du froid"]'::jsonb,'["Stress, a threat display, or excitement","That it is hungry","That it is about to shed","That it is sick from cold"]'::jsonb,0,'Het opzwellen en donker kleuren van de baard is een waarschuwings- of stresssignaal.','Le gonflement et l''assombrissement de la barbe est un signal d''avertissement ou de stress.','Puffing up and darkening the beard is a warning or stress signal.'),
(3,'tekst','Hoe til je een baardagame best correct op?','Comment doit-on correctement soulever un dragon barbu ?','How should you correctly pick up a bearded dragon?','["Met beide handen het volledige lichaam ondersteunend","Bij de staart optillen","Snel van bovenaf grijpen","Nooit optillen, enkel laten lopen"]'::jsonb,'["Avec les deux mains en soutenant tout le corps","En le soulevant par la queue","En l''attrapant rapidement par le dessus","Ne jamais le soulever, juste le laisser marcher"]'::jsonb,'["With both hands, supporting the whole body","By lifting it by the tail","By grabbing quickly from above","Never lift it, just let it walk"]'::jsonb,0,'Het lichaam ondersteunen voorkomt letsel en stress, want plotse bewegingen van boven kunnen als roofdiergedrag overkomen.','Soutenir le corps évite les blessures et le stress, car un geste brusque par le dessus peut ressembler à une attaque.','Supporting the body prevents injury and stress, as sudden overhead movement can resemble predator behaviour.'),
(3,'tekst','Waarom moet je jonge kinderen begeleiden bij contact met een baardagame op de kinderboerderij?','Pourquoi faut-il accompagner les jeunes enfants lors du contact avec un dragon barbu à la ferme pédagogique ?','Why should young children be supervised when in contact with a bearded dragon at a city farm?','["Om stress bij het dier en hygiëneproblemen te vermijden","Omdat baardagamen erg gevaarlijk gif hebben","Omdat ze snel bijten zonder reden","Begeleiding is niet nodig, ze zijn nooit stressgevoelig"]'::jsonb,'["Pour éviter le stress de l''animal et les problèmes d''hygiène","Parce que les dragons barbus ont un venin dangereux","Parce qu''ils mordent souvent sans raison","Aucun accompagnement n''est nécessaire"]'::jsonb,'["To avoid stressing the animal and hygiene issues","Because bearded dragons have dangerous venom","Because they often bite without reason","Supervision isn''t needed, they never get stressed"]'::jsonb,0,'Ruw hanteren stresst het dier en reptielen kunnen salmonella dragen, dus handen wassen na contact is belangrijk.','Une manipulation brusque stresse l''animal et les reptiles peuvent porter la salmonelle, se laver les mains est important.','Rough handling stresses the animal and reptiles can carry salmonella, so washing hands after contact matters.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- cavia: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'cavia' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Hoeveel vloeroppervlakte heeft een cavia minimaal nodig?','De quelle surface au sol minimale un cochon d''Inde a-t-il besoin ?','How much floor space does a guinea pig need at minimum?',
 '["0,5 m² per dier","2 m² per dier","0,1 m² per dier","Geen vaste norm nodig"]'::jsonb,
 '["0,5 m² par animal","2 m² par animal","0,1 m² par animal","Aucune norme fixe nécessaire"]'::jsonb,
 '["0.5 m² per animal","2 m² per animal","0.1 m² per animal","No fixed standard needed"]'::jsonb,
 0,'Cavia''s hebben minstens 0,5 m² per dier nodig om te kunnen rennen, verstoppen en exploreren.','Les cochons d''Inde ont besoin d''au moins 0,5 m² par animal pour courir, se cacher et explorer.','Guinea pigs need at least 0.5 m² per animal to run, hide and explore.'),
(1,'tekst','Wat hoort altijd in een caviaverblijf aanwezig te zijn?','Qu''est-ce qui doit toujours se trouver dans l''enclos d''un cochon d''Inde ?','What should always be present in a guinea pig enclosure?',
 '["Een loopwiel","Schuilplaatsen zoals hutjes of buizen","Een waterbad","Niets, een kale bodem is best"]'::jsonb,
 '["Une roue d''exercice","Des cachettes comme des huttes ou tubes","Un bain d''eau","Rien, un sol nu est préférable"]'::jsonb,
 '["An exercise wheel","Hiding spots like huts or tubes","A water bath","Nothing, a bare floor is best"]'::jsonb,
 1,'Cavia''s zijn prooidieren en hebben schuilplaatsen nodig om zich veilig te voelen en stress te vermijden.','Les cochons d''Inde sont des proies et ont besoin de cachettes pour se sentir en sécurité.','Guinea pigs are prey animals and need hiding spots to feel safe and avoid stress.'),
(1,'tekst','Bij welke temperatuur voelt een cavia zich het best?','À quelle température un cochon d''Inde se sent-il le mieux ?','At what temperature does a guinea pig feel best?',
 '["Tussen 5 en 10°C","Tussen 30 en 35°C","Tussen 18 en 22°C","Temperatuur maakt niet uit"]'::jsonb,
 '["Entre 5 et 10°C","Entre 30 et 35°C","Entre 18 et 22°C","La température n''a pas d''importance"]'::jsonb,
 '["Between 5 and 10°C","Between 30 and 35°C","Between 18 and 22°C","Temperature doesn''t matter"]'::jsonb,
 2,'Cavia''s zijn gevoelig aan tocht en extreme temperaturen; 18-22°C is ideaal voor hun welzijn.','Les cochons d''Inde sont sensibles aux courants d''air et aux températures extrêmes ; 18-22°C est idéal.','Guinea pigs are sensitive to drafts and extreme temperatures; 18-22°C is ideal for their wellbeing.'),
(1,'tekst','Waarom is een loopwiel ongeschikt voor cavia''s?','Pourquoi une roue d''exercice est-elle inadaptée aux cochons d''Inde ?','Why is an exercise wheel unsuitable for guinea pigs?',
 '["Ze houden niet van bewegen","Hun rug kan zich niet krommen zoals bij muizen, dit is schadelijk","Wielen zijn te duur","Ze passen er niet in"]'::jsonb,
 '["Ils n''aiment pas bouger","Leur dos ne peut pas se courber comme celui d''une souris, c''est nocif","Les roues coûtent trop cher","Ils n''y tiennent pas"]'::jsonb,
 '["They don''t like moving","Their spine can''t curve like a mouse''s, which is harmful","Wheels are too expensive","They don''t fit in them"]'::jsonb,
 1,'De wervelkolom van een cavia is niet gebouwd om te krommen in een wiel, wat rugletsel kan veroorzaken.','La colonne vertébrale d''un cochon d''Inde n''est pas faite pour se courber dans une roue, ce qui peut blesser le dos.','A guinea pig''s spine isn''t built to curve in a wheel, which can cause back injury.'),
(2,'tekst','Waarom hebben cavia''s dagelijks vitamine C nodig via hun voeding?','Pourquoi les cochons d''Inde ont-ils besoin de vitamine C chaque jour dans leur alimentation ?','Why do guinea pigs need daily vitamin C in their diet?',
 '["Ze kunnen dit zelf aanmaken, dus het is niet nodig","Ze kunnen geen vitamine C aanmaken en worden anders ziek","Het maakt hun vacht glanzender","Vitamine C is giftig voor hen"]'::jsonb,
 '["Ils le produisent eux-mêmes, donc inutile","Ils ne peuvent pas produire de vitamine C et tombent malades sinon","Cela rend leur pelage plus brillant","La vitamine C leur est toxique"]'::jsonb,
 '["They can produce it themselves, so it''s unnecessary","They cannot produce vitamin C and get sick without it","It makes their coat shinier","Vitamin C is toxic to them"]'::jsonb,
 1,'Cavia''s missen, net als mensen, het enzym om vitamine C aan te maken en hebben het dus via voeding nodig, anders krijgen ze scheurbuik.','Comme les humains, les cochons d''Inde manquent de l''enzyme pour produire de la vitamine C et doivent l''obtenir par l''alimentation, sinon ils développent le scorbut.','Like humans, guinea pigs lack the enzyme to make vitamin C and must get it from food, or they develop scurvy.'),
(2,'tekst','Wat vormt de basis van een gezond caviadieet?','Quelle est la base d''une alimentation saine pour le cochon d''Inde ?','What forms the basis of a healthy guinea pig diet?',
 '["Onbeperkt hooi","Vooral pellets","Vooral fruit","Voornamelijk brood en granen"]'::jsonb,
 '["Du foin à volonté","Surtout des granulés","Surtout des fruits","Principalement du pain et des céréales"]'::jsonb,
 '["Unlimited hay","Mostly pellets","Mostly fruit","Mainly bread and grains"]'::jsonb,
 0,'Hooi moet altijd onbeperkt beschikbaar zijn: het houdt de darmen en tanden van de cavia gezond.','Le foin doit toujours être disponible à volonté : il maintient les intestins et les dents du cochon d''Inde en bonne santé.','Hay should always be available unlimited: it keeps a guinea pig''s gut and teeth healthy.'),
(2,'tekst','Waarom groeien de tanden van een cavia levenslang door?','Pourquoi les dents du cochon d''Inde poussent-elles toute sa vie ?','Why do a guinea pig''s teeth grow continuously throughout its life?',
 '["Dit is een ziekte","Om voldoende ruwvoer te kunnen afslijten en kauwen","Ze verliezen tanden vaak","Alleen bij oude dieren"]'::jsonb,
 '["C''est une maladie","Pour pouvoir user les dents grâce aux fibres et mâcher","Ils perdent souvent des dents","Seulement chez les animaux âgés"]'::jsonb,
 '["It''s a disease","So they can wear them down chewing fibrous food","They often lose teeth","Only in old animals"]'::jsonb,
 1,'De tanden groeien continu door en worden afgesleten door het kauwen op hooi; te weinig ruwvoer leidt tot gebitsproblemen.','Les dents poussent en continu et s''usent en mâchant du foin ; trop peu de fibres cause des problèmes dentaires.','Teeth grow continuously and are worn down by chewing hay; too little fibre causes dental problems.'),
(2,'tekst','Wat is een teken van ziekte bij een cavia waarbij je snel een dierenarts moet raadplegen?','Quel signe de maladie chez un cochon d''Inde nécessite de consulter rapidement un vétérinaire ?','What sign of illness in a guinea pig should prompt a quick vet visit?',
 '["Normale eetlust","Stoppen met eten gedurende enkele uren","Rustig slapen overdag","Regelmatig knagen op hooi"]'::jsonb,
 '["Appétit normal","Arrêt de l''alimentation pendant quelques heures","Dormir tranquillement le jour","Ronger régulièrement du foin"]'::jsonb,
 '["Normal appetite","Stopping eating for a few hours","Sleeping calmly during the day","Regularly gnawing on hay"]'::jsonb,
 1,'Cavia''s hebben een snelle darmpassage nodig; stoppen met eten kan al na enkele uren levensbedreigend zijn.','Les cochons d''Inde ont besoin d''un transit rapide ; arrêter de manger peut devenir dangereux en quelques heures.','Guinea pigs need constant gut movement; stopping eating can become life-threatening within hours.'),
(3,'tekst','Waarom mag een cavia nooit alleen gehouden worden?','Pourquoi un cochon d''Inde ne doit-il jamais être détenu seul ?','Why should a guinea pig never be kept alone?',
 '["Ze zijn van nature solitair","Het zijn sociale dieren die soortgenoten nodig hebben","Ze vechten altijd met elkaar","Alleen wijfjes hebben gezelschap nodig"]'::jsonb,
 '["Ils sont naturellement solitaires","Ce sont des animaux sociaux ayant besoin de congénères","Ils se battent toujours entre eux","Seules les femelles ont besoin de compagnie"]'::jsonb,
 '["They are naturally solitary","They are social animals needing companions","They always fight with each other","Only females need companionship"]'::jsonb,
 1,'Cavia''s leven in het wild in groepen en hebben soortgenoten nodig om zich veilig en gelukkig te voelen.','À l''état sauvage, les cochons d''Inde vivent en groupes et ont besoin de congénères pour se sentir en sécurité et heureux.','In the wild guinea pigs live in groups and need companions to feel safe and happy.'),
(3,'tekst','Hoe til je een cavia het beste correct op?','Comment soulever correctement un cochon d''Inde ?','How should you correctly pick up a guinea pig?',
 '["Aan de oren","Met beide handen, één onder de borst en één onder het achterwerk","Aan de nekvel","Aan de pootjes"]'::jsonb,
 '["Par les oreilles","Avec les deux mains, une sous la poitrine et une sous l''arrière-train","Par la peau du cou","Par les pattes"]'::jsonb,
 '["By the ears","With both hands, one under the chest and one under the rear","By the scruff of the neck","By the legs"]'::jsonb,
 1,'Een cavia moet met beide handen ondersteund worden zodat het lichaam volledig gedragen wordt en niet kan wegglijden.','Un cochon d''Inde doit être soutenu à deux mains pour que tout le corps soit porté sans risque de chute.','A guinea pig should be supported with both hands so the whole body is held and can''t slip.'),
(3,'tekst','Wat betekent het geluid "wheeking" (een luid piepje) meestal bij een cavia?','Que signifie généralement le "wheek" (cri aigu) chez le cochon d''Inde ?','What does a guinea pig''s loud "wheeking" sound usually mean?',
 '["Pijn","Opwinding, vaak in verwachting van eten","Agressie","Ze zijn ziek"]'::jsonb,
 '["Douleur","Excitation, souvent en attendant la nourriture","Agressivité","Ils sont malades"]'::jsonb,
 '["Pain","Excitement, often in anticipation of food","Aggression","They are ill"]'::jsonb,
 1,'Wheeken is een herkenbaar geluid dat cavia''s maken wanneer ze eten verwachten of enthousiast zijn.','Le "wheek" est un son reconnaissable que les cochons d''Inde émettent en anticipant la nourriture ou par enthousiasme.','Wheeking is a recognisable sound guinea pigs make when anticipating food or feeling excited.'),
(3,'tekst','Hoe reageert een cavia meestal wanneer die schrikt?','Comment un cochon d''Inde réagit-il généralement lorsqu''il a peur ?','How does a guinea pig usually react when startled?',
 '["Het verstijft en blijft doodstil zitten (freeze)","Het gaat meteen slapen","Het klimt hoog omhoog","Het maakt luid keelgeschraap"]'::jsonb,
 '["Il se fige et reste immobile (freeze)","Il s''endort immédiatement","Il grimpe très haut","Il émet un raclement de gorge fort"]'::jsonb,
 '["It freezes and stays completely still","It goes to sleep immediately","It climbs up high","It makes a loud throat rasp"]'::jsonb,
 0,'Cavia''s zijn prooidieren die bij schrik vaak bevriezen (freeze) in plaats van te vluchten, als overlevingsstrategie.','Les cochons d''Inde, proies dans la nature, se figent souvent (freeze) plutôt que de fuir, comme stratégie de survie.','Guinea pigs are prey animals that often freeze when startled rather than flee, as a survival strategy.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- geit: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'geit' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Wat hebben geiten nodig in hun stal?','De quoi les chèvres ont-elles besoin dans leur abri ?','What do goats need in their shelter?',
 '["Een droge, tochtvrije ligplaats met stro","Enkel een betonnen vloer zonder stro","Continu fel licht","Een volledig kale ruimte"]'::jsonb,
 '["Un couchage sec et sans courants d''air, avec de la paille","Uniquement un sol en béton sans paille","Une lumière vive en continu","Un espace totalement vide"]'::jsonb,
 '["A dry, draught-free bedded area with straw","Only a concrete floor without straw","Continuous bright light","A completely bare space"]'::jsonb,
 0,'Geiten zijn gevoelig voor vocht en tocht, droog stro voorkomt longproblemen.','Les chèvres sont sensibles à l''humidité, la paille sèche prévient les problèmes pulmonaires.','Goats are sensitive to damp; dry straw helps prevent lung problems.'),
(1,'tekst','Waarom hebben geiten graag verhogingen om op te klimmen?','Pourquoi les chèvres aiment-elles grimper sur des surélévations ?','Why do goats like elevated platforms to climb on?',
 '["Klimmen is natuurlijk gedrag en verrijkt hun omgeving","Geiten klimmen nooit","Het is enkel gevaarlijk","Ze doen dit om te ontsnappen"]'::jsonb,
 '["Grimper est un comportement naturel qui enrichit leur environnement","Les chèvres ne grimpent jamais","C''est uniquement dangereux","Elles le font pour s''échapper"]'::jsonb,
 '["Climbing is natural behaviour that enriches their environment","Goats never climb","It is only dangerous","They do it to escape"]'::jsonb,
 0,'In het wild leven geiten op rotsachtig terrein, klimstructuren stimuleren hun natuurlijk gedrag.','À l''état sauvage, les chèvres vivent en terrain rocheux, les structures stimulent ce comportement naturel.','In the wild, goats live on rocky terrain; climbing structures encourage this natural behaviour.'),
(1,'tekst','Hoeveel ruimte hebben geiten minstens nodig om zich normaal te gedragen?','De combien d''espace minimum les chèvres ont-elles besoin ?','How much space do goats need at minimum to behave normally?',
 '["Voldoende ruimte om te bewegen, spelen en elkaar te ontwijken","Amper genoeg om te blijven staan","Geiten hebben geen ruimte nodig","Enkel een klein hok van 1m²"]'::jsonb,
 '["Assez d''espace pour bouger, jouer et s''éviter","À peine assez pour rester debout","Les chèvres n''ont pas besoin d''espace","Un enclos d''à peine 1 m²"]'::jsonb,
 '["Enough space to move, play and avoid each other","Barely enough to stand","Goats do not need space","A tiny 1m² pen"]'::jsonb,
 0,'Te weinig ruimte leidt tot stress en conflicten binnen de groep.','Un espace insuffisant entraîne stress et conflits au sein du groupe.','Too little space leads to stress and conflict within the group.'),
(1,'tekst','Waarom moeten geiten nooit alleen gehouden worden?','Pourquoi les chèvres ne doivent-elles jamais être seules ?','Why should goats never be kept alone?',
 '["Het zijn kuddedieren die gezelschap nodig hebben","Geiten verkiezen eenzaamheid","Het maakt geen verschil","Ze worden agressiever in een groep"]'::jsonb,
 '["Ce sont des animaux grégaires qui ont besoin de compagnie","Les chèvres préfèrent la solitude","Cela ne fait aucune différence","Elles deviennent plus agressives en groupe"]'::jsonb,
 '["They are herd animals that need companionship","Goats prefer solitude","It makes no difference","They become more aggressive in groups"]'::jsonb,
 0,'Een geit alleen houden veroorzaakt ernstige stress omdat ze van nature in een kudde leven.','Garder une chèvre seule cause un stress sévère car elle vit naturellement en troupeau.','Keeping a single goat causes severe stress because they naturally live in herds.'),
(2,'tekst','Wat vormt het grootste deel van het dieet van een geit?','Quelle est la base principale de l''alimentation d''une chèvre ?','What forms the main part of a goat''s diet?',
 '["Hooi, gras en bladeren van struiken","Enkel brood en koekjes","Vlees en vis","Uitsluitend krachtvoer"]'::jsonb,
 '["Foin, herbe et feuilles d''arbustes","Uniquement du pain et des biscuits","Viande et poisson","Uniquement des aliments concentrés"]'::jsonb,
 '["Hay, grass and shrub leaves","Only bread and biscuits","Meat and fish","Exclusively concentrated feed"]'::jsonb,
 0,'Geiten zijn browsers die van nature bladeren en struiken eten, niet enkel gras zoals schapen.','Les chèvres sont des broutardes qui mangent feuilles et arbustes, pas seulement de l''herbe comme les moutons.','Goats are browsers that naturally eat leaves and shrubs, not just grass like sheep.'),
(2,'tekst','Waarom is het gevaarlijk om geiten brood of koekjes te voeren?','Pourquoi est-il dangereux de nourrir les chèvres avec du pain ou des biscuits ?','Why is it dangerous to feed goats bread or biscuits?',
 '["Het kan hun spijsvertering verstoren en tot gezondheidsproblemen leiden","Geiten hebben dit net nodig","Het is hun favoriete en gezondste voer","Het heeft geen enkel effect"]'::jsonb,
 '["Cela peut perturber leur digestion et causer des problèmes de santé","Les chèvres en ont justement besoin","C''est leur nourriture préférée et la plus saine","Cela n''a aucun effet"]'::jsonb,
 '["It can upset their digestion and cause health problems","Goats actually need this","It is their favourite and healthiest food","It has no effect at all"]'::jsonb,
 0,'Suikerrijk en bewerkt voedsel kan pensproblemen en zwaarlijvigheid veroorzaken bij geiten.','Les aliments sucrés et transformés peuvent causer des troubles ruminaux et l''obésité chez les chèvres.','Sugary, processed food can cause rumen problems and obesity in goats.'),
(2,'tekst','Waarom moeten geitenhoeven regelmatig bijgesneden worden?','Pourquoi les sabots des chèvres doivent-ils être taillés régulièrement ?','Why do goat hooves need regular trimming?',
 '["Om overgroei, kreupelheid en infecties te voorkomen","Hoeven groeien niet bij geiten","Het is enkel esthetisch","Het is nooit nodig"]'::jsonb,
 '["Pour éviter la surcroissance, la boiterie et les infections","Les sabots des chèvres ne poussent pas","C''est purement esthétique","Ce n''est jamais nécessaire"]'::jsonb,
 '["To prevent overgrowth, lameness and infections","Goat hooves do not grow","It is purely cosmetic","It is never necessary"]'::jsonb,
 0,'Onverzorgde hoeven kunnen misvormen en pijnlijke infecties veroorzaken, geregeld bijsnijden is nodig.','Des sabots non entretenus peuvent se déformer et provoquer des infections douloureuses.','Untrimmed hooves can deform and cause painful infections; regular trimming is needed.'),
(2,'tekst','Wat is een teken van goede gezondheid bij een geit?','Quel est un signe de bonne santé chez une chèvre ?','What is a sign of good health in a goat?',
 '["Heldere ogen, actieve houding en goede eetlust","Doffe vacht en volledige lusteloosheid","Constant hoesten","Weigeren van alle voedsel"]'::jsonb,
 '["Des yeux clairs, une attitude active et un bon appétit","Un pelage terne et une léthargie totale","Une toux constante","Refuser toute nourriture"]'::jsonb,
 '["Bright eyes, an active posture and good appetite","Dull coat and complete lethargy","Constant coughing","Refusing all food"]'::jsonb,
 0,'Een gezonde geit is alert en nieuwsgierig, met een glanzende vacht en goede eetlust.','Une chèvre en bonne santé est alerte et curieuse, avec un pelage brillant et un bon appétit.','A healthy goat is alert and curious, with a shiny coat and good appetite.'),
(3,'tekst','Waarom vormen geiten een strikte rangorde binnen de kudde?','Pourquoi les chèvres établissent-elles une hiérarchie stricte dans le troupeau ?','Why do goats form a strict hierarchy within the herd?',
 '["Het regelt toegang tot voedsel en rustplekken en vermindert conflicten","Geiten hebben geen sociale structuur","Het is enkel toeval","Rangorde bestaat niet bij geiten"]'::jsonb,
 '["Cela règle l''accès à la nourriture et aux zones de repos, réduisant les conflits","Les chèvres n''ont pas de structure sociale","C''est purement aléatoire","La hiérarchie n''existe pas chez les chèvres"]'::jsonb,
 '["It regulates access to food and resting spots and reduces conflict","Goats have no social structure","It is purely random","Hierarchy does not exist in goats"]'::jsonb,
 0,'Een duidelijke rangorde vermindert agressie doordat elke geit haar plaats in de groep kent.','Une hiérarchie claire réduit l''agressivité car chaque chèvre connaît sa place dans le groupe.','A clear hierarchy reduces aggression because each goat knows its place in the group.'),
(3,'tekst','Hoe reageer je best als een geit tegen je opdringt om aandacht?','Comment réagir si une chèvre s''appuie sur vous pour attirer l''attention ?','How should you react if a goat pushes against you for attention?',
 '["Rustig blijven en grenzen stellen zonder te straffen","Onmiddellijk wegrennen","De geit hard wegduwen","Haar altijd meteen voeren als beloning"]'::jsonb,
 '["Rester calme et poser des limites sans punir","Fuir immédiatement","Repousser violemment la chèvre","Toujours la nourrir immédiatement en récompense"]'::jsonb,
 '["Stay calm and set boundaries without punishing","Run away immediately","Push the goat away hard","Always feed her immediately as a reward"]'::jsonb,
 0,'Duidelijke, kalme grenzen leren geiten respectvol gedrag zonder angst te veroorzaken.','Des limites claires et calmes apprennent aux chèvres un comportement respectueux sans provoquer de peur.','Clear, calm boundaries teach goats respectful behaviour without causing fear.'),
(3,'tekst','Wat betekent het als een geit met de horens stampt of duwt tegen soortgenoten?','Que signifie une chèvre qui donne des coups de cornes à ses congénères ?','What does it mean when a goat headbutts other goats?',
 '["Het is vaak een teken van rangordebepaling of spel","Het gebeurt nooit bij geiten","Het betekent altijd ernstige ziekte","Het is puur toeval zonder betekenis"]'::jsonb,
 '["C''est souvent un signe d''établissement de hiérarchie ou de jeu","Cela n''arrive jamais chez les chèvres","Cela signifie toujours une maladie grave","C''est purement aléatoire sans signification"]'::jsonb,
 '["It is often a sign of establishing rank or play","It never happens with goats","It always means serious illness","It is purely random and meaningless"]'::jsonb,
 0,'Koppen stoten is normaal sociaal gedrag bij geiten om rang te bepalen of te spelen.','Le heurtement des têtes est un comportement social normal pour établir un rang ou jouer.','Headbutting is normal social behaviour in goats to establish rank or play.'),
(3,'tekst','Waarom is het belangrijk om kinderen te leren hoe ze veilig met geiten omgaan op de kinderboerderij?','Pourquoi est-il important d''apprendre aux enfants à interagir en sécurité avec les chèvres ?','Why is it important to teach children safe interaction with goats?',
 '["Om stress bij dieren en ongelukken bij kinderen te voorkomen","Geiten zijn nooit gevaarlijk voor kinderen","Kinderen weten dit vanzelf","Het is niet nodig op een kinderboerderij"]'::jsonb,
 '["Pour éviter le stress chez les animaux et les accidents chez les enfants","Les chèvres ne sont jamais dangereuses pour les enfants","Les enfants le savent naturellement","Ce n''est pas nécessaire à la ferme urbaine"]'::jsonb,
 '["To prevent animal stress and accidents involving children","Goats are never dangerous to children","Children know this naturally","It is unnecessary at a city farm"]'::jsonb,
 0,'Rustig en respectvol gedrag zorgt voor een veilige, positieve ervaring voor kind en dier.','Un comportement calme et respectueux garantit une expérience sûre et positive pour l''enfant et l''animal.','Calm, respectful behaviour ensures a safe, positive experience for both child and animal.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- hamster: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'hamster' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Hoeveel oppervlakte heeft een goudhamster minimaal nodig?','De quelle surface minimale un hamster doré a-t-il besoin ?','How much floor space does a golden hamster need at minimum?',
 '["Ongeveer 800 cm²","Minstens 100 x 50 cm bodemoppervlak","Een schoenendoos volstaat","10 cm²"]'::jsonb,
 '["Environ 800 cm²","Au moins 100 x 50 cm de surface au sol","Une boîte à chaussures suffit","10 cm²"]'::jsonb,
 '["About 800 cm²","At least 100 x 50 cm of floor space","A shoebox is enough","10 cm²"]'::jsonb,
 1,'Hamsters leggen in het wild kilometers af; een groot kooioppervlak van minstens 100x50 cm is nodig om normaal gedrag te vertonen.','Dans la nature, les hamsters parcourent des kilomètres ; une cage d''au moins 100x50 cm est nécessaire pour un comportement normal.','In the wild hamsters roam kilometres; a cage of at least 100x50 cm is needed for normal behaviour.'),
(1,'tekst','Hoe diep moet de strooisellaag minstens zijn zodat een hamster kan graven?','Quelle doit être l''épaisseur minimale de litière pour que le hamster puisse creuser ?','How deep should the bedding layer be at minimum so a hamster can dig?',
 '["2 cm","20-30 cm","Graven is niet nodig","1 cm volstaat"]'::jsonb,
 '["2 cm","20-30 cm","Creuser n''est pas nécessaire","1 cm suffit"]'::jsonb,
 '["2 cm","20-30 cm","Digging isn''t necessary","1 cm is enough"]'::jsonb,
 1,'Hamsters zijn gravers die in de natuur tunnels graven; 20-30 cm strooisel maakt dit natuurlijk gedrag mogelijk.','Les hamsters sont des fouisseurs qui creusent des tunnels dans la nature ; 20-30 cm de litière permet ce comportement naturel.','Hamsters are diggers that build tunnels in the wild; 20-30 cm of bedding allows this natural behaviour.'),
(1,'tekst','Waarom is een loopwiel met een gesloten (niet-ladder) rijvlak belangrijk voor een hamster?','Pourquoi une roue d''exercice à surface pleine (sans barreaux) est-elle importante pour un hamster ?','Why is a solid-surface (non-rung) exercise wheel important for a hamster?',
 '["Om esthetische redenen","Om rugletsels en beknelde pootjes te voorkomen","Om de kooi te versieren","Ladders zijn net beter"]'::jsonb,
 '["Pour des raisons esthétiques","Pour éviter les blessures au dos et les pattes coincées","Pour décorer la cage","Les barreaux sont en fait préférables"]'::jsonb,
 '["For aesthetic reasons","To prevent back injuries and trapped feet","To decorate the cage","Rungs are actually better"]'::jsonb,
 1,'Een wiel met spijlen kan pootjes bekneld raken; een gesloten loopvlak van minstens 20-28 cm diameter is veiliger.','Une roue à barreaux peut coincer les pattes ; une surface pleine d''au moins 20-28 cm de diamètre est plus sûre.','A rung wheel can trap feet; a solid running surface of at least 20-28 cm diameter is safer.'),
(1,'tekst','Op welk tijdstip is een hamster het meest actief?','À quel moment de la journée un hamster est-il le plus actif ?','At what time of day is a hamster most active?',
 '["''s Ochtends vroeg","Overdag","''s Nachts (nocturnaal)","Nooit, ze slapen bijna altijd"]'::jsonb,
 '["Tôt le matin","Pendant la journée","La nuit (nocturne)","Jamais, ils dorment presque tout le temps"]'::jsonb,
 '["Early in the morning","During the day","At night (nocturnal)","Never, they sleep almost all the time"]'::jsonb,
 2,'Hamsters zijn nachtdieren en worden overdag best niet gestoord, zodat ze voldoende rust krijgen.','Les hamsters sont nocturnes et il vaut mieux ne pas les déranger la journée pour qu''ils se reposent suffisamment.','Hamsters are nocturnal and should ideally not be disturbed during the day so they get enough rest.'),
(2,'tekst','Waarom stoppen hamsters voedsel in hun wangzakken?','Pourquoi les hamsters stockent-ils de la nourriture dans leurs bajoues ?','Why do hamsters store food in their cheek pouches?',
 '["Om indruk te maken op soortgenoten","Om voedsel te verzamelen en op te slaan als voorraad","Omdat ze niet kunnen kauwen","Uit verveling"]'::jsonb,
 '["Pour impressionner leurs congénères","Pour rassembler et stocker de la nourriture en réserve","Parce qu''ils ne peuvent pas mâcher","Par ennui"]'::jsonb,
 '["To impress other hamsters","To gather and store food as a reserve","Because they can''t chew","Out of boredom"]'::jsonb,
 1,'Wangzakken laten hamsters toe voedsel te verzamelen en later terug te trekken naar hun nest als voorraad.','Les bajoues permettent aux hamsters de rassembler de la nourriture et de la rapporter à leur nid comme réserve.','Cheek pouches let hamsters gather food and carry it back to their nest as a reserve.'),
(2,'tekst','Welk voedsel is gevaarlijk voor hamsters?','Quel aliment est dangereux pour les hamsters ?','Which food is dangerous for hamsters?',
 '["Speciaal hamsterkorrelvoer","Verse groenten in kleine hoeveelheid","Citrusvruchten en te veel vochtige snacks","Hooi"]'::jsonb,
 '["Granulés spéciaux pour hamster","Légumes frais en petite quantité","Agrumes et trop de collations humides","Foin"]'::jsonb,
 '["Special hamster pellet food","Fresh vegetables in small amounts","Citrus fruit and too many moist snacks","Hay"]'::jsonb,
 2,'Citrusvruchten en te vochtige snacks kunnen diarree veroorzaken bij hamsters, wat snel gevaarlijk wordt door hun kleine formaat.','Les agrumes et les collations trop humides peuvent causer des diarrhées, dangereuses vu leur petite taille.','Citrus fruit and overly moist snacks can cause diarrhoea, which is dangerous given a hamster''s small size.'),
(2,'tekst','Waarom is het belangrijk dat een hamster kan knagen op hard voedsel of takken?','Pourquoi est-il important qu''un hamster puisse ronger des aliments durs ou des branches ?','Why is it important for a hamster to be able to gnaw on hard food or branches?',
 '["Om verveling te uiten","Om de doorgroeiende tanden af te slijten","Puur voor de smaak","Het is niet belangrijk"]'::jsonb,
 '["Pour exprimer l''ennui","Pour user les dents qui poussent en continu","Uniquement pour le goût","Ce n''est pas important"]'::jsonb,
 '["To express boredom","To wear down their continuously growing teeth","Purely for taste","It isn''t important"]'::jsonb,
 1,'De tanden van een hamster groeien levenslang door; knagen op hard materiaal houdt ze op de juiste lengte.','Les dents d''un hamster poussent toute sa vie ; ronger des matériaux durs les maintient à la bonne longueur.','A hamster''s teeth grow continuously; gnawing on hard material keeps them at the right length.'),
(2,'tekst','Wat is een teken van gezondheidsproblemen bij een hamster?','Quel est un signe de problème de santé chez un hamster ?','What is a sign of health problems in a hamster?',
 '["Actief graven ''s nachts","Natte, plakkerige staart of vacht","Wangzakken gebruiken","Normale slaap overdag"]'::jsonb,
 '["Creuser activement la nuit","Queue ou pelage humide et collant","Utiliser ses bajoues","Sommeil normal le jour"]'::jsonb,
 '["Actively digging at night","Wet, sticky tail or fur","Using cheek pouches","Normal daytime sleep"]'::jsonb,
 1,'Een natte staart ("wet tail") wijst vaak op een ernstige darminfectie en vereist dringend dierenartsbezoek.','Une "queue mouillée" indique souvent une infection intestinale grave nécessitant une visite vétérinaire urgente.','A "wet tail" often indicates a serious intestinal infection requiring urgent veterinary care.'),
(3,'tekst','Kunnen de meeste hamstersoorten samen met soortgenoten gehuisvest worden?','La plupart des espèces de hamsters peuvent-elles être hébergées avec des congénères ?','Can most hamster species be housed together with others?',
 '["Ja, altijd in groep","Nee, Syrische hamsters zijn solitair en moeten alleen gehouden worden","Alleen mannetjes kunnen samen","Ja, in grote kolonies zoals cavia''s"]'::jsonb,
 '["Oui, toujours en groupe","Non, les hamsters syriens sont solitaires et doivent vivre seuls","Seuls les mâles peuvent cohabiter","Oui, en grandes colonies comme les cochons d''Inde"]'::jsonb,
 '["Yes, always in a group","No, Syrian hamsters are solitary and must live alone","Only males can live together","Yes, in large colonies like guinea pigs"]'::jsonb,
 1,'Syrische hamsters zijn territoriaal en solitair; samen huisvesten leidt vaak tot hevige gevechten.','Les hamsters syriens sont territoriaux et solitaires ; les héberger ensemble mène souvent à de violents combats.','Syrian hamsters are territorial and solitary; housing them together often leads to serious fighting.'),
(3,'tekst','Hoe til je een hamster het best op?','Comment soulever un hamster correctement ?','How should you best pick up a hamster?',
 '["Aan de staart","Rustig met beide handen als een kommetje, van onderaf","Nooit, je mag ze niet aanraken","Aan de nekvel vastgrijpen"]'::jsonb,
 '["Par la queue","Doucement à deux mains en forme de coupe, par-dessous","Jamais, on ne doit pas les toucher","En le saisissant par la peau du cou"]'::jsonb,
 '["By the tail","Gently with both hands cupped, scooping from below","Never, they shouldn''t be touched","By grabbing the scruff of the neck"]'::jsonb,
 1,'Hamsters voelen zich veiliger wanneer ze met beide handen als een kommetje worden opgetild in plaats van van bovenaf gegrepen.','Les hamsters se sentent plus en sécurité lorsqu''ils sont soulevés à deux mains en coupe plutôt qu''attrapés par le dessus.','Hamsters feel safer when scooped up with both hands cupped rather than grabbed from above.'),
(3,'tekst','Waarom moet je een hamster nooit plots wakker maken overdag?','Pourquoi ne faut-il jamais réveiller brusquement un hamster le jour ?','Why should you never suddenly wake a hamster during the day?',
 '["Het kan schrikken en bijten uit zelfverdediging","Hamsters worden er blij van","Het heeft geen effect","Hamsters slapen nooit overdag"]'::jsonb,
 '["Il peut avoir peur et mordre par autodéfense","Cela rend le hamster heureux","Cela n''a aucun effet","Les hamsters ne dorment jamais le jour"]'::jsonb,
 '["It can startle them into biting out of self-defence","It makes hamsters happy","It has no effect","Hamsters never sleep during the day"]'::jsonb,
 0,'Een plots gewekte hamster kan schrikken en instinctief bijten omdat hij zich bedreigd voelt, laat hem rustig wakker worden.','Un hamster réveillé brusquement peut mordre par instinct de survie, mieux vaut le laisser se réveiller tranquillement.','A suddenly woken hamster may bite instinctively out of fear; let it wake up calmly.'),
(3,'tekst','Wat betekent het wanneer een hamster rechtop staat met de pootjes omhoog?','Que signifie un hamster debout, les pattes avant levées ?','What does it mean when a hamster stands upright with paws raised?',
 '["Het is aan het spelen","Het voelt zich bedreigd en waarschuwt of verdedigt zich","Het vraagt om eten","Het heeft honger naar water"]'::jsonb,
 '["Il joue","Il se sent menacé et avertit ou se défend","Il demande à manger","Il a soif"]'::jsonb,
 '["It is playing","It feels threatened and is warning or defending itself","It is asking for food","It is thirsty"]'::jsonb,
 1,'Deze houding is een verdedigingshouding waarbij de hamster groter probeert te lijken uit angst of bedreiging.','Cette posture est une position défensive où le hamster tente de paraître plus grand par peur ou menace.','This posture is a defensive stance where the hamster tries to look bigger out of fear or threat.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- kanarie: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'kanarie' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Wat is de minimale kooibreedte voor een kanarie?','Quelle est la largeur minimale de cage pour un canari ?','What is the minimum cage width for a canary?','["20 cm", "60-80 cm", "10 cm", "Breedte doet er niet toe"]'::jsonb,'["20 cm", "60-80 cm", "10 cm", "La largeur n''a pas d''importance"]'::jsonb,'["20 cm", "60-80 cm", "10 cm", "Width doesn''t matter"]'::jsonb,1,'Kanaries vliegen liever horizontaal dan verticaal, dus een brede kooi is belangrijker dan een hoge.','Les canaris préfèrent voler horizontalement plutôt que verticalement, une cage large est donc plus importante qu''une cage haute.','Canaries prefer flying horizontally rather than vertically, so a wide cage matters more than a tall one.'),
  (1,'tekst','Waarom is directe tocht gevaarlijk voor een kanarie?','Pourquoi les courants d''air directs sont-ils dangereux pour un canari ?','Why are direct drafts dangerous for a canary?','["Ze houden ervan", "Kan longontsteking veroorzaken", "Het maakt hen sterker", "Er is geen gevaar"]'::jsonb,'["Ils adorent ça", "Peut provoquer une pneumonie", "Cela les rend plus forts", "Il n''y a aucun danger"]'::jsonb,'["They love it", "Can cause pneumonia", "It makes them stronger", "There is no danger"]'::jsonb,1,'Kanaries zijn gevoelig voor koude tocht, wat luchtweginfecties kan veroorzaken.','Les canaris sont sensibles aux courants d''air froid, ce qui peut causer des infections respiratoires.','Canaries are sensitive to cold drafts, which can cause respiratory infections.'),
  (1,'tekst','Welke temperatuur verdraagt een kanarie het best?','Quelle température un canari supporte-t-il le mieux ?','What temperature does a canary tolerate best?','["5-10°C", "18-22°C", "30-35°C", "Temperatuur maakt niet uit"]'::jsonb,'["5-10°C", "18-22°C", "30-35°C", "La température n''a pas d''importance"]'::jsonb,'["5-10°C", "18-22°C", "30-35°C", "Temperature doesn''t matter"]'::jsonb,1,'Een stabiele kamertemperatuur tussen 18 en 22°C zonder plotselinge schommelingen is ideaal.','Une température ambiante stable entre 18 et 22°C sans variations brusques est idéale.','A stable room temperature between 18 and 22°C without sudden swings is ideal.'),
  (1,'tekst','Wat is een goede locatie voor een kanariekooi in huis?','Quel est un bon emplacement pour une cage à canari à la maison ?','What is a good location for a canary cage at home?','["Direct in fel zonlicht zonder schaduw", "Rustige plek met deels natuurlijk licht en geen tocht", "In de badkamer bij stoom", "Naast de luidsprekers"]'::jsonb,'["En plein soleil sans ombre", "Endroit calme avec lumière naturelle partielle et sans courant d''air", "Dans la salle de bain avec vapeur", "À côté des enceintes"]'::jsonb,'["Direct in harsh sunlight with no shade", "Quiet spot with some natural light and no draft", "In the bathroom with steam", "Next to the speakers"]'::jsonb,1,'Een rustige, tochtvrije plek met wisselend licht en donker helpt het natuurlijke ritme te behouden.','Un endroit calme, sans courant d''air, avec alternance de lumière aide à préserver le rythme naturel.','A quiet, draft-free spot with alternating light helps maintain a natural rhythm.'),
  (2,'tekst','Waaruit bestaat een uitgebalanceerd dieet voor een kanarie?','En quoi consiste une alimentation équilibrée pour un canari ?','What does a balanced diet for a canary consist of?','["Enkel zaadmengeling", "Zaadmengeling aangevuld met groenten en fruit", "Enkel brood", "Enkel water en zaad zonder groenten"]'::jsonb,'["Uniquement un mélange de graines", "Mélange de graines complété de légumes et fruits", "Uniquement du pain", "Uniquement eau et graines sans légumes"]'::jsonb,'["Seed mix only", "Seed mix supplemented with vegetables and fruit", "Bread only", "Only water and seed, no vegetables"]'::jsonb,1,'Verse groenten en fruit leveren vitamines die in een puur zaaddieet ontbreken.','Les légumes et fruits frais apportent des vitamines absentes d''une alimentation exclusivement à base de graines.','Fresh vegetables and fruit provide vitamins missing from a pure seed diet.'),
  (2,'tekst','Wat mag je een kanarie nooit geven?','Que ne faut-il jamais donner à un canari ?','What should you never give a canary?','["Sla", "Chocolade", "Appel", "Wortel"]'::jsonb,'["De la laitue", "Du chocolat", "Une pomme", "Une carotte"]'::jsonb,'["Lettuce", "Chocolate", "Apple", "Carrot"]'::jsonb,1,'Chocolade bevat theobromine, giftig voor vogels en kan hartfalen veroorzaken.','Le chocolat contient de la théobromine, toxique pour les oiseaux et pouvant causer une insuffisance cardiaque.','Chocolate contains theobromine, toxic to birds and can cause heart failure.'),
  (2,'tekst','Waarom heeft een kanarie grit of kalk nodig?','Pourquoi un canari a-t-il besoin de grit ou de calcium ?','Why does a canary need grit or calcium?','["Voor de smaak", "Voor spijsvertering en botgezondheid, vooral bij leggende vrouwtjes", "Het is niet nodig", "Om te spelen"]'::jsonb,'["Pour le goût", "Pour la digestion et la santé osseuse, surtout chez les femelles pondeuses", "Ce n''est pas nécessaire", "Pour jouer"]'::jsonb,'["For taste", "For digestion and bone health, especially in laying females", "It''s not necessary", "To play"]'::jsonb,1,'Kalk ondersteunt eierproductie en botsterkte, grit helpt bij het verteren van zaden.','Le calcium soutient la production d''œufs et la solidité osseuse, le grit aide à digérer les graines.','Calcium supports egg production and bone strength; grit helps digest seeds.'),
  (2,'tekst','Hoe merk je dat een kanarie mogelijk ziek is?','Comment remarque-t-on qu''un canari est peut-être malade ?','How can you tell a canary might be sick?','["Hij zingt de hele dag", "Verminderde zang, opgezette veren, zit stil op de bodem", "Hij eet normaal", "Hij baadt elke dag"]'::jsonb,'["Il chante toute la journée", "Chant réduit, plumes ébouriffées, reste immobile au sol", "Il mange normalement", "Il se baigne chaque jour"]'::jsonb,'["It sings all day", "Reduced singing, fluffed feathers, sitting still at the bottom", "It eats normally", "It bathes daily"]'::jsonb,1,'Minder zingen en stil op de bodem zitten zijn vaak vroege tekenen van ziekte.','Chanter moins et rester immobile au sol sont souvent des signes précoces de maladie.','Singing less and sitting still on the cage floor are often early signs of illness.'),
  (3,'tekst','Waarom zingen mannetjeskanaries meer dan vrouwtjes?','Pourquoi les canaris mâles chantent-ils plus que les femelles ?','Why do male canaries sing more than females?','["Toeval", "Territoriaal en baltsgedrag", "Ze zijn banger", "Ze zijn zieker"]'::jsonb,'["Le hasard", "Comportement territorial et de parade nuptiale", "Ils ont plus peur", "Ils sont plus malades"]'::jsonb,'["Coincidence", "Territorial and courtship behaviour", "They are more scared", "They are sicker"]'::jsonb,1,'Zang bij mannetjes dient om territorium af te bakenen en vrouwtjes aan te trekken.','Le chant des mâles sert à délimiter le territoire et attirer les femelles.','Male song serves to mark territory and attract females.'),
  (3,'tekst','Kunnen twee mannelijke kanaries best samen in één kooi leven?','Deux canaris mâles peuvent-ils bien vivre ensemble dans une seule cage ?','Can two male canaries live well together in one cage?','["Ja, altijd probleemloos", "Vaak niet, ze kunnen territoriaal vechten", "Enkel als ze familie zijn", "Kanaries leven nooit samen"]'::jsonb,'["Oui, toujours sans problème", "Souvent pas, ils peuvent se battre pour le territoire", "Seulement s''ils sont de la même famille", "Les canaris ne vivent jamais ensemble"]'::jsonb,'["Yes, always without issue", "Often not, they may fight over territory", "Only if they''re related", "Canaries never live together"]'::jsonb,1,'Mannelijke kanaries zijn vaak territoriaal en kunnen elkaar verwonden in een gedeelde kooi.','Les canaris mâles sont souvent territoriaux et peuvent se blesser dans une cage partagée.','Male canaries are often territorial and can injure each other in a shared cage.'),
  (3,'tekst','Hoe reageert een kanarie meestal op hanteren met de hand?','Comment un canari réagit-il généralement à la manipulation manuelle ?','How does a canary typically react to hand-handling?','["Ze houden er erg van", "Ze vinden dit meestal stresserend, in tegenstelling tot parkieten", "Ze zoeken het zelf op", "Het maakt hen niets uit"]'::jsonb,'["Ils adorent ça", "Ils trouvent cela généralement stressant, contrairement aux perruches", "Ils le recherchent eux-mêmes", "Cela leur est indifférent"]'::jsonb,'["They love it very much", "They usually find it stressful, unlike budgies", "They seek it out themselves", "They don''t mind at all"]'::jsonb,1,'Kanaries zijn doorgaans kijkvogels; ze worden best niet gedwongen om vastgehouden te worden.','Les canaris sont généralement des oiseaux d''observation ; il vaut mieux ne pas les forcer à être manipulés.','Canaries are generally ''watch'' birds; they shouldn''t be forced to be handled.'),
  (3,'tekst','Wat kan helpen om verveling bij een kanarie te voorkomen?','Qu''est-ce qui peut aider à prévenir l''ennui chez un canari ?','What can help prevent boredom in a canary?','["Kooi altijd afgedekt houden", "Speeltjes, takjes en variatie in de omgeving", "Nooit iets veranderen", "De kooi zo klein mogelijk houden"]'::jsonb,'["Garder la cage toujours couverte", "Jouets, branches et variation dans l''environnement", "Ne jamais rien changer", "Garder la cage aussi petite que possible"]'::jsonb,'["Always keeping the cage covered", "Toys, twigs and variation in the environment", "Never changing anything", "Keeping the cage as small as possible"]'::jsonb,1,'Verrijking zoals natuurlijke takjes en afwisseling stimuleert natuurlijk gedrag en voorkomt verveling.','Un enrichissement comme des branches naturelles et de la variété stimule le comportement naturel et évite l''ennui.','Enrichment like natural twigs and variety stimulates natural behaviour and prevents boredom.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- konijn: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'konijn' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Hoeveel ruimte heeft een konijn minstens nodig om te kunnen huppelen en rennen?','De combien d''espace un lapin a-t-il au minimum besoin pour sautiller et courir ?','How much space does a rabbit need at minimum to hop and run?',
 '["Een kooi van 60x40 cm volstaat","Minstens 3 tot 6 m² vrije ruimte","Konijnen hebben geen ruimte nodig","1 m² is voldoende"]'::jsonb,
 '["Une cage de 60x40 cm suffit","Au moins 3 à 6 m² d''espace libre","Les lapins n''ont pas besoin d''espace","1 m² suffit"]'::jsonb,
 '["A 60x40 cm cage is enough","At least 3 to 6 m² of free space","Rabbits don''t need space","1 m² is enough"]'::jsonb,
 1,'Konijnen hebben dagelijks veel bewegingsruimte nodig om te springen en rennen; minstens 3 à 6 m² is aanbevolen.','Les lapins ont besoin de beaucoup d''espace quotidien pour sauter et courir ; au moins 3 à 6 m² sont recommandés.','Rabbits need lots of daily movement space to hop and run; at least 3 to 6 m² is recommended.'),
(1,'tekst','Waarom moeten konijnen altijd met minstens twee gehouden worden?','Pourquoi les lapins doivent-ils toujours être détenus à deux minimum ?','Why should rabbits always be kept in pairs at minimum?',
 '["Het zijn sociale kuddedieren die gezelschap nodig hebben","Ze vervelen zich anders van elkaar","Het is wettelijk verplicht overal","Ze eten anders niet"]'::jsonb,
 '["Ce sont des animaux sociaux ayant besoin de compagnie","Sinon ils s''ennuient l''un de l''autre","C''est obligatoire partout par la loi","Sinon ils ne mangent pas"]'::jsonb,
 '["They are social herd animals needing companionship","Otherwise they get bored of each other","It''s legally required everywhere","Otherwise they won''t eat"]'::jsonb,
 0,'Konijnen zijn van nature sociale dieren die in het wild in groepen leven en gezelschap van soortgenoten nodig hebben.','Les lapins sont des animaux naturellement sociaux qui vivent en groupe à l''état sauvage et ont besoin de compagnie.','Rabbits are naturally social animals that live in groups in the wild and need companionship.'),
(1,'tekst','Wat is essentieel in een konijnenverblijf om gravend gedrag mogelijk te maken?','Qu''est-ce qui est essentiel dans un enclos de lapin pour permettre le comportement de fouissage ?','What is essential in a rabbit enclosure to allow digging behaviour?',
 '["Een gladde plastic bodem","Een graafbak of dikke laag stro/grond","Een loopwiel","Niets speciaals nodig"]'::jsonb,
 '["Un sol en plastique lisse","Un bac à creuser ou une épaisse couche de paille/terre","Une roue d''exercice","Rien de spécial n''est nécessaire"]'::jsonb,
 '["A smooth plastic floor","A digging box or thick layer of straw/soil","An exercise wheel","Nothing special is needed"]'::jsonb,
 1,'Konijnen graven van nature holen; een graafbak biedt hen de kans op dit natuurlijke gedrag zonder schade te veroorzaken.','Les lapins creusent naturellement des terriers ; un bac à creuser leur permet ce comportement sans causer de dégâts.','Rabbits naturally dig burrows; a digging box lets them express this natural behaviour without causing damage.'),
(1,'tekst','Waarom is schaduw en beschutting tegen hitte cruciaal voor buitenkonijnen?','Pourquoi l''ombre et la protection contre la chaleur sont-elles cruciales pour les lapins d''extérieur ?','Why is shade and heat protection crucial for outdoor rabbits?',
 '["Konijnen kunnen niet goed zweten en oververhitten snel","Ze houden niet van zonlicht","Het is enkel esthetisch","Konijnen slapen liever in de zon"]'::jsonb,
 '["Les lapins ne transpirent pas bien et surchauffent vite","Ils n''aiment pas la lumière du soleil","C''est purement esthétique","Les lapins préfèrent dormir au soleil"]'::jsonb,
 '["Rabbits cannot sweat well and overheat quickly","They dislike sunlight","It''s purely aesthetic","Rabbits prefer sleeping in the sun"]'::jsonb,
 0,'Konijnen kunnen nauwelijks zweten en lopen snel risico op hitteslag; schaduw en ventilatie zijn levensnoodzakelijk bij warm weer.','Les lapins transpirent à peine et risquent vite un coup de chaleur ; l''ombre et la ventilation sont vitales par temps chaud.','Rabbits can barely sweat and risk heatstroke quickly; shade and ventilation are vital in hot weather.'),
(2,'tekst','Wat moet het grootste deel van het konijnendieet uitmaken?','Quelle doit être la principale composante de l''alimentation du lapin ?','What should make up the largest part of a rabbit''s diet?',
 '["Pellets/korrels","Hooi (ongeveer 80%)","Wortelen","Brood en granen"]'::jsonb,
 '["Granulés","Le foin (environ 80%)","Les carottes","Le pain et les céréales"]'::jsonb,
 '["Pellets","Hay (about 80%)","Carrots","Bread and grains"]'::jsonb,
 1,'Hooi moet ongeveer 80% van het dieet vormen; het is essentieel voor de spijsvertering en het gebit van konijnen.','Le foin doit représenter environ 80% du régime ; il est essentiel pour la digestion et les dents des lapins.','Hay should make up about 80% of the diet; it is essential for a rabbit''s digestion and teeth.'),
(2,'tekst','Waarom zijn wortelen en fruit slechts als kleine traktatie geschikt voor konijnen?','Pourquoi les carottes et fruits ne conviennent-ils qu''en petite friandise pour les lapins ?','Why are carrots and fruit only suitable as small treats for rabbits?',
 '["Ze zijn giftig","Ze bevatten veel suiker en kunnen obesitas of gebitsproblemen veroorzaken","Konijnen lusten ze niet","Ze bevatten geen voedingswaarde"]'::jsonb,
 '["Ils sont toxiques","Ils contiennent beaucoup de sucre et peuvent causer obésité ou problèmes dentaires","Les lapins ne les aiment pas","Ils n''ont aucune valeur nutritive"]'::jsonb,
 '["They are toxic","They are high in sugar and can cause obesity or dental issues","Rabbits dislike them","They have no nutritional value"]'::jsonb,
 1,'Wortelen en fruit zijn suikerrijk; te veel kan leiden tot overgewicht en tandproblemen bij konijnen.','Les carottes et fruits sont riches en sucre ; un excès peut causer surpoids et problèmes dentaires chez le lapin.','Carrots and fruit are high in sugar; too much can lead to obesity and dental problems in rabbits.'),
(2,'tekst','Wat is een teken van een ernstig gezondheidsprobleem bij konijnen dat spoedeisende zorg vereist?','Quel signe chez le lapin nécessite une intervention vétérinaire urgente ?','What sign in rabbits requires urgent veterinary care?',
 '["Normaal keutelen","Volledig stoppen met eten (gastro-intestinale stase)","Actief hooi eten","Rustig zitten in de schaduw"]'::jsonb,
 '["Crottes normales","Arrêt total de l''alimentation (stase gastro-intestinale)","Manger activement du foin","Rester tranquille à l''ombre"]'::jsonb,
 '["Normal droppings","Complete stop in eating (gastrointestinal stasis)","Actively eating hay","Sitting calmly in the shade"]'::jsonb,
 1,'Konijnen hebben een continu werkend spijsverteringsstelsel; wanneer ze stoppen met eten kan dit binnen uren levensgevaarlijk worden.','Le système digestif du lapin doit fonctionner en continu ; un arrêt de l''alimentation peut devenir mortel en quelques heures.','A rabbit''s digestive system must work continuously; stopping eating can become life-threatening within hours.'),
(2,'tekst','Waarom moeten de tanden van een konijn regelmatig gecontroleerd worden?','Pourquoi les dents d''un lapin doivent-elles être vérifiées régulièrement ?','Why should a rabbit''s teeth be checked regularly?',
 '["Ze groeien levenslang door en kunnen te lang worden","Ze vallen vaak uit","Konijnen hebben maar 2 tanden","Dit is niet nodig"]'::jsonb,
 '["Elles poussent toute la vie et peuvent devenir trop longues","Elles tombent souvent","Les lapins n''ont que 2 dents","Ce n''est pas nécessaire"]'::jsonb,
 '["They grow continuously and can become too long","They often fall out","Rabbits only have 2 teeth","It isn''t necessary"]'::jsonb,
 0,'Zonder voldoende hooi om op te kauwen kunnen de doorgroeiende tanden te lang worden en pijnlijke gebitsproblemen veroorzaken.','Sans assez de foin à mâcher, les dents qui poussent en continu peuvent devenir trop longues et douloureuses.','Without enough hay to chew, continuously growing teeth can become too long and cause painful problems.'),
(3,'tekst','Hoe til je een konijn correct op om letsel te vermijden?','Comment soulever correctement un lapin pour éviter les blessures ?','How should you correctly lift a rabbit to avoid injury?',
 '["Aan de oren","Met één hand onder de borst en één onder het achterwerk, rug ondersteund","Aan de nekvel alleen","Aan de pootjes optillen"]'::jsonb,
 '["Par les oreilles","Une main sous la poitrine et une sous l''arrière-train, dos soutenu","Uniquement par la peau du cou","Par les pattes"]'::jsonb,
 '["By the ears","One hand under the chest and one under the rear, back supported","Only by the scruff","By the legs"]'::jsonb,
 1,'De rug van een konijn moet altijd ondersteund worden; verkeerd optillen kan tot ernstig ruggenmergletsel leiden.','Le dos d''un lapin doit toujours être soutenu ; un mauvais soulèvement peut causer de graves blessures à la colonne.','A rabbit''s back must always be supported; incorrect lifting can cause serious spinal injury.'),
(3,'tekst','Wat betekent het wanneer een konijn met zijn achterpoot op de grond stampt?','Que signifie un lapin qui tape du pied arrière sur le sol ?','What does it mean when a rabbit thumps its hind foot on the ground?',
 '["Het is blij en speels","Het waarschuwt voor gevaar of is gestrest","Het vraagt om eten","Het wil slapen"]'::jsonb,
 '["Il est heureux et joueur","Il avertit d''un danger ou est stressé","Il demande à manger","Il veut dormir"]'::jsonb,
 '["It is happy and playful","It is warning of danger or is stressed","It is asking for food","It wants to sleep"]'::jsonb,
 1,'Stampen is een alarmsignaal waarmee konijnen soortgenoten waarschuwen voor gevaar, of het toont stress of onrust.','Le tapement est un signal d''alarme par lequel les lapins avertissent leurs congénères d''un danger, ou montre du stress.','Thumping is an alarm signal rabbits use to warn others of danger, or it shows stress.'),
(3,'tekst','Waarom mag je een konijn nooit plots achteropkomen of vastgrijpen?','Pourquoi ne faut-il jamais surprendre ou saisir brusquement un lapin par derrière ?','Why should you never suddenly approach or grab a rabbit from behind?',
 '["Konijnen zijn prooidieren en schrikken hierdoor hevig","Konijnen vinden het net leuk","Het heeft geen effect op hen","Konijnen zien niets aankomen sowieso"]'::jsonb,
 '["Les lapins sont des proies et sont fortement effrayés","Les lapins adorent ça","Cela n''a aucun effet sur eux","Les lapins ne voient rien venir de toute façon"]'::jsonb,
 '["Rabbits are prey animals and get badly frightened","Rabbits actually enjoy it","It has no effect on them","Rabbits can''t see anything coming anyway"]'::jsonb,
 0,'Konijnen zijn prooidieren met een sterk vluchtinstinct; plotse bewegingen van achteren kunnen paniek en letsel veroorzaken.','Les lapins sont des proies avec un fort instinct de fuite ; des mouvements soudains par derrière peuvent causer panique et blessures.','Rabbits are prey animals with a strong flight instinct; sudden movements from behind can cause panic and injury.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- korenslang: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'korenslang' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Wat is een goede warme kant-temperatuur (basking spot) voor een korenslang?','Quelle est une bonne température du côté chaud (zone de chauffe) pour un serpent des blés ?','What is a good warm-side (basking) temperature for a corn snake?','["Ongeveer 29-32°C","Ongeveer 40°C","Ongeveer 18°C","Kamertemperatuur volstaat"]'::jsonb,'["Environ 29-32°C","Environ 40°C","Environ 18°C","La température ambiante suffit"]'::jsonb,'["About 29-32°C","About 40°C","About 18°C","Room temperature is enough"]'::jsonb,0,'Een thermisch gradiënt laat de slang zelf de juiste temperatuur kiezen door te bewegen tussen warme en koele kant.','Un gradient thermique permet au serpent de choisir lui-même la bonne température en se déplaçant.','A thermal gradient lets the snake choose its own ideal temperature by moving around the enclosure.'),
(1,'tekst','Waarom heeft een korenslang een koele kant nodig in het terrarium?','Pourquoi un serpent des blés a-t-il besoin d''un côté frais dans le terrarium ?','Why does a corn snake need a cool side in its enclosure?','["Om te kunnen afkoelen en spijsvertering te regelen","Om te kunnen slapen","Omdat het decoratief is","Slangen hebben geen koele kant nodig"]'::jsonb,'["Pour pouvoir se refroidir et réguler la digestion","Pour pouvoir dormir","Pour la décoration","Les serpents n''ont pas besoin de côté frais"]'::jsonb,'["To cool down and help regulate digestion","So it can sleep","Just for decoration","Snakes don''t need a cool side"]'::jsonb,0,'Slangen zijn koudbloedig en gebruiken de omgeving om hun lichaamstemperatuur en spijsvertering te regelen.','Les serpents sont à sang froid et utilisent leur environnement pour réguler leur température et digestion.','Snakes are cold-blooded and use their environment to regulate body temperature and digestion.'),
(1,'tekst','Welke luchtvochtigheid is meestal geschikt voor een korenslang?','Quel taux d''humidité convient généralement à un serpent des blés ?','What humidity level is generally suitable for a corn snake?','["Ongeveer 40-50%","Ongeveer 90-100%","Ongeveer 5%","Luchtvochtigheid maakt niet uit"]'::jsonb,'["Environ 40-50%","Environ 90-100%","Environ 5%","L''humidité n''a pas d''importance"]'::jsonb,'["About 40-50%","About 90-100%","About 5%","Humidity doesn''t matter"]'::jsonb,0,'Te lage luchtvochtigheid kan problemen geven bij het vervellen, te hoge kan huidproblemen veroorzaken.','Une humidité trop basse peut poser problème lors de la mue, trop élevée peut causer des problèmes cutanés.','Too-low humidity can cause shedding problems, too-high humidity can cause skin issues.'),
(1,'tekst','Wat moet altijd aanwezig zijn in het terrarium van een korenslang?','Qu''est-ce qui doit toujours être présent dans le terrarium d''un serpent des blés ?','What should always be present in a corn snake''s enclosure?','["Een schuilplaats en vers water","Enkel een lamp","Een grote vijver","Niets, kaal terrarium is beter"]'::jsonb,'["Une cachette et de l''eau fraîche","Uniquement une lampe","Un grand bassin","Rien, un terrarium vide est préférable"]'::jsonb,'["A hiding spot and fresh water","Only a lamp","A large pond","Nothing, a bare enclosure is better"]'::jsonb,0,'Schuilplaatsen verminderen stress en vers water is essentieel, ook al drinken slangen niet vaak.','Les cachettes réduisent le stress et l''eau fraîche est essentielle, même si les serpents boivent peu souvent.','Hides reduce stress and fresh water is essential, even though snakes don''t drink very often.'),
(2,'tekst','Wat eten korenslangen normaal gezien?','Que mangent normalement les serpents des blés ?','What do corn snakes normally eat?','["Kleine knaagdieren zoals muizen","Enkel groenten","Insecten en fruit","Alleen melk"]'::jsonb,'["De petits rongeurs comme des souris","Uniquement des légumes","Des insectes et des fruits","Uniquement du lait"]'::jsonb,'["Small rodents like mice","Only vegetables","Insects and fruit","Only milk"]'::jsonb,0,'Korenslangen zijn vleeseters en jagen in het wild op knaagdieren en kleine vogels.','Les serpents des blés sont carnivores et chassent rongeurs et petits oiseaux dans la nature.','Corn snakes are carnivores that hunt rodents and small birds in the wild.'),
(2,'tekst','Hoe vaak moet een volwassen korenslang meestal gevoed worden?','À quelle fréquence un serpent des blés adulte doit-il généralement être nourri ?','How often does an adult corn snake usually need to be fed?','["Ongeveer om de 7-10 dagen","Elke dag","Eén keer per jaar","Nooit, ze eten zelfstandig"]'::jsonb,'["Environ tous les 7-10 jours","Chaque jour","Une fois par an","Jamais, ils se nourrissent seuls"]'::jsonb,'["About every 7-10 days","Every day","Once a year","Never, they feed themselves"]'::jsonb,0,'Volwassen korenslangen hebben een trage stofwisseling en hoeven niet vaak te eten.','Les serpents des blés adultes ont un métabolisme lent et n''ont pas besoin de manger souvent.','Adult corn snakes have a slow metabolism and don''t need to eat often.'),
(2,'tekst','Waarom is een vervelprobleem (stukjes oude huid blijven vastzitten) een teken van slechte verzorging?','Pourquoi un problème de mue (morceaux de peau qui restent collés) est-il un signe de mauvais soin ?','Why is a shedding problem (retained bits of old skin) a sign of poor care?','["Het wijst vaak op te lage luchtvochtigheid","Het is altijd normaal en onschadelijk","Het betekent dat de slang te veel eet","Het komt door te veel licht"]'::jsonb,'["Cela indique souvent une humidité trop basse","C''est toujours normal et sans danger","Cela signifie que le serpent mange trop","C''est dû à trop de lumière"]'::jsonb,'["It often points to too-low humidity","It is always normal and harmless","It means the snake eats too much","It is caused by too much light"]'::jsonb,0,'Onvoldoende vochtigheid tijdens de vervelling kan ervoor zorgen dat de huid niet volledig loslaat.','Une humidité insuffisante pendant la mue peut empêcher la peau de se détacher complètement.','Insufficient humidity during shedding can cause the skin to not fully release.'),
(2,'tekst','Wat is een teken van een gezonde korenslang?','Quel est un signe d''un serpent des blés en bonne santé ?','What is a sign of a healthy corn snake?','["Heldere ogen en regelmatige eetlust","Constant verstopt zonder te bewegen","Zichtbare mijten en wonden","Aanhoudend gewichtsverlies"]'::jsonb,'["Des yeux clairs et un appétit régulier","Toujours caché sans bouger","Des acariens et blessures visibles","Une perte de poids continue"]'::jsonb,'["Clear eyes and a regular appetite","Constantly hiding without moving","Visible mites and wounds","Continuous weight loss"]'::jsonb,0,'Gezonde slangen hebben heldere ogen, een gladde huid en een normaal eetpatroon.','Un serpent en bonne santé a les yeux clairs, une peau lisse et un appétit normal.','Healthy snakes have clear eyes, smooth skin and a normal appetite pattern.'),
(3,'tekst','Wanneer kun je een korenslang best niet vastnemen?','Quand vaut-il mieux ne pas manipuler un serpent des blés ?','When is it best not to handle a corn snake?','["Tijdens de vervelling","Elk moment is prima","Enkel bij zonsopgang","Nooit, handling maakt niet uit"]'::jsonb,'["Pendant la mue","N''importe quand, c''est très bien","Uniquement au lever du soleil","Jamais, la manipulation n''a pas d''importance"]'::jsonb,'["During shedding","Any time is fine","Only at sunrise","Never, handling doesn''t matter"]'::jsonb,0,'Tijdens de vervelling zien slangen slechter en kunnen ze extra gestrest of defensief reageren.','Pendant la mue, les serpents voient moins bien et peuvent réagir avec plus de stress ou de défense.','During shedding, snakes see less well and can react more defensively or stressed.'),
(3,'tekst','Hoe herken je stress bij een korenslang?','Comment reconnaît-on le stress chez un serpent des blés ?','How can you recognise stress in a corn snake?','["Sissen, aanhoudend verstoppen of weigeren te eten","Ze kwispelen met de staart van blijdschap","Ze slapen altijd 20 uur per dag, dat is stress","Stress is bij slangen niet zichtbaar"]'::jsonb,'["Siffler, se cacher constamment ou refuser de manger","Elles remuent la queue de joie","Elles dorment toujours 20h/jour, c''est du stress","Le stress n''est pas visible chez les serpents"]'::jsonb,'["Hissing, constant hiding, or refusing food","Wagging their tail happily","Sleeping 20 hours a day is stress","Stress isn''t visible in snakes"]'::jsonb,0,'Gedragsveranderingen zoals sissen, verstopgedrag of eetweigering kunnen wijzen op stress of onwelzijn.','Des changements de comportement comme siffler, se cacher ou refuser de manger peuvent indiquer du stress.','Behaviour changes like hissing, hiding, or refusing food can indicate stress or discomfort.'),
(3,'tekst','Hoe til je een korenslang best op?','Comment doit-on soulever un serpent des blés ?','How should you best pick up a corn snake?','["Rustig en met steun voor het volledige lichaam","Enkel bij de staart optillen","Snel vastgrijpen bij de kop","Nooit ondersteunen, laten hangen"]'::jsonb,'["Calmement, en soutenant tout le corps","En le soulevant uniquement par la queue","En l''attrapant rapidement par la tête","Sans jamais le soutenir, le laisser pendre"]'::jsonb,'["Calmly, supporting the whole body","Only lifting it by the tail","Grabbing it quickly by the head","Never supporting it, letting it dangle"]'::jsonb,0,'Het lichaam volledig ondersteunen voorkomt stress en verwondingen bij de slang.','Soutenir tout le corps évite le stress et les blessures chez le serpent.','Fully supporting the body prevents stress and injury to the snake.'),
(3,'tekst','Waarom is een deksel met slot belangrijk bij het terrarium van een korenslang?','Pourquoi un couvercle verrouillable est-il important pour le terrarium d''un serpent des blés ?','Why is a locking lid important for a corn snake''s enclosure?','["Korenslangen zijn sterke ontsnappingskunstenaars","Om licht buiten te houden","Om het terrarium te versieren","Slangen kunnen niet klimmen dus het is niet nodig"]'::jsonb,'["Les serpents des blés s''échappent très facilement","Pour bloquer la lumière","Pour décorer le terrarium","Les serpents ne grimpent pas donc ce n''est pas nécessaire"]'::jsonb,'["Corn snakes are skilled escape artists","To keep light out","To decorate the enclosure","Snakes can''t climb so it''s unnecessary"]'::jsonb,0,'Korenslangen kunnen door kleine openingen glippen en zijn bekend als echte ontsnappingsmeesters.','Les serpents des blés peuvent se faufiler par de petites ouvertures et sont connus pour s''échapper facilement.','Corn snakes can squeeze through small gaps and are well known for escaping enclosures.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- landschildpad: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'landschildpad' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Waarom hebben landschildpadden een groot buitenverblijf nodig als het weer het toelaat?','Pourquoi les tortues terrestres ont-elles besoin d''un grand enclos extérieur quand le temps le permet ?','Why do tortoises need a large outdoor enclosure when weather allows?','["Voor natuurlijk zonlicht, beweging en gevarieerd gedrag","Om te kunnen zwemmen in diep water","Omdat ze binnen niet kunnen ademen","Ruimte is niet belangrijk voor schildpadden"]'::jsonb,'["Pour la lumière naturelle, le mouvement et un comportement varié","Pour pouvoir nager en eau profonde","Parce qu''elles ne peuvent pas respirer à l''intérieur","L''espace n''est pas important pour les tortues"]'::jsonb,'["For natural sunlight, exercise and varied behaviour","To be able to swim in deep water","Because they can''t breathe indoors","Space isn''t important for tortoises"]'::jsonb,0,'Natuurlijk zonlicht levert UVB dat essentieel is voor de aanmaak van vitamine D3.','La lumière naturelle du soleil fournit des UVB essentiels à la production de vitamine D3.','Natural sunlight provides UVB that is essential for vitamin D3 production.'),
(1,'tekst','Wat hebben waterschildpadden nodig naast water om in te zwemmen?','De quoi les tortues aquatiques ont-elles besoin en plus de l''eau pour nager ?','What do aquatic turtles need besides water to swim in?','["Een droog eiland of basking-plek om te zonnen","Enkel meer water, niets anders","Volledige duisternis","Een tweede aquarium zonder water"]'::jsonb,'["Une île sèche ou zone de bain de soleil","Simplement plus d''eau, rien d''autre","L''obscurité totale","Un deuxième aquarium sans eau"]'::jsonb,'["A dry basking island or spot to sunbathe","Just more water, nothing else","Complete darkness","A second tank without water"]'::jsonb,0,'Waterschildpadden moeten volledig kunnen opdrogen op een basking-plek om schimmel- en huidproblemen te voorkomen.','Les tortues aquatiques doivent pouvoir sécher complètement sur une zone de bain pour éviter les mycoses.','Aquatic turtles must be able to fully dry off on a basking spot to prevent fungal and skin problems.'),
(1,'tekst','Welke rol speelt UVB-belichting voor schildpadden?','Quel est le rôle de l''éclairage UVB pour les tortues ?','What role does UVB lighting play for tortoises?','["Het helpt vitamine D3 en een gezond schild vormen","Het dient enkel om het terrarium te verlichten","UVB is schadelijk voor schildpadden","Schildpadden hebben geen licht nodig"]'::jsonb,'["Elle aide à produire la vitamine D3 et une carapace saine","Elle sert uniquement à éclairer le terrarium","L''UVB est nocif pour les tortues","Les tortues n''ont pas besoin de lumière"]'::jsonb,'["It helps produce vitamin D3 and a healthy shell","It''s just to light up the enclosure","UVB is harmful to tortoises","Tortoises don''t need light"]'::jsonb,0,'Zonder UVB kan het schild zwak en misvormd groeien door gebrekkige calciumopname.','Sans UVB, la carapace peut devenir faible et déformée à cause d''une mauvaise absorption du calcium.','Without UVB, the shell can grow weak and deformed due to poor calcium absorption.'),
(1,'tekst','Wat is belangrijk bij het inrichten van een schuilplaats voor een schildpad?','Qu''est-ce qui est important dans l''aménagement d''une cachette pour une tortue ?','What is important when setting up a hiding spot for a tortoise?','["Ze moet donker, veilig en op maat van het dier zijn","Ze moet doorzichtig zijn zodat bezoekers alles zien","Schuilplaatsen zijn niet nodig","Ze moet altijd verlicht zijn"]'::jsonb,'["Elle doit être sombre, sûre et adaptée à la taille de l''animal","Elle doit être transparente pour que les visiteurs voient tout","Les cachettes ne sont pas nécessaires","Elle doit toujours être éclairée"]'::jsonb,'["It should be dark, safe and sized for the animal","It should be transparent so visitors can see everything","Hiding spots aren''t necessary","It should always be lit"]'::jsonb,0,'Een veilige schuilplaats vermindert stress en geeft de schildpad controle over haar omgeving.','Une cachette sûre réduit le stress et donne à la tortue un contrôle sur son environnement.','A safe hiding spot reduces stress and gives the tortoise control over its environment.'),
(2,'tekst','Wat eten de meeste landschildpadden hoofdzakelijk?','Que mangent principalement la plupart des tortues terrestres ?','What do most tortoises mainly eat?','["Vezelrijke groenten en onkruid","Vlees en vis","Enkel fruit","Kattenvoeding"]'::jsonb,'["Des légumes fibreux et des herbes sauvages","De la viande et du poisson","Uniquement des fruits","De la nourriture pour chat"]'::jsonb,'["Fibre-rich greens and weeds","Meat and fish","Only fruit","Cat food"]'::jsonb,0,'De meeste landschildpadden zijn herbivoren en hebben veel vezels nodig voor een gezonde spijsvertering.','La plupart des tortues terrestres sont herbivores et ont besoin de fibres pour une bonne digestion.','Most tortoises are herbivores and need lots of fibre for healthy digestion.'),
(2,'tekst','Waarom is te veel fruit slecht voor een landschildpad?','Pourquoi trop de fruits est-il mauvais pour une tortue terrestre ?','Why is too much fruit bad for a tortoise?','["Te veel suiker kan de darmflora en gezondheid verstoren","Fruit is giftig voor schildpadden","Schildpadden kunnen fruit niet ruiken","Fruit veroorzaakt schildgroei"]'::jsonb,'["Trop de sucre peut perturber la flore intestinale et la santé","Les fruits sont toxiques pour les tortues","Les tortues ne peuvent pas sentir les fruits","Les fruits provoquent la croissance de la carapace"]'::jsonb,'["Too much sugar can disrupt gut flora and health","Fruit is toxic to tortoises","Tortoises can''t smell fruit","Fruit causes shell growth"]'::jsonb,0,'Overmatige suiker uit fruit kan leiden tot spijsverteringsproblemen en parasietenoverlast.','Un excès de sucre provenant des fruits peut causer des problèmes digestifs et favoriser les parasites.','Excess sugar from fruit can lead to digestive issues and parasite problems.'),
(2,'tekst','Wat is een teken van een ongezond schild bij een schildpad?','Quel est un signe d''une carapace en mauvaise santé chez une tortue ?','What is a sign of an unhealthy shell in a tortoise?','["Zachte plekken of onregelmatige groei (piramidevorming)","Een glanzend, glad oppervlak","Een gelijkmatige lichte kleur","Normale groeiringen"]'::jsonb,'["Des zones molles ou une croissance irrégulière (pyramidage)","Une surface brillante et lisse","Une couleur claire uniforme","Des anneaux de croissance normaux"]'::jsonb,'["Soft patches or irregular growth (pyramiding)","A shiny, smooth surface","An even light colour","Normal growth rings"]'::jsonb,0,'Piramidevorming en zachte plekken wijzen vaak op een tekort aan calcium, UVB of een verkeerd dieet.','Le pyramidage et les zones molles indiquent souvent un manque de calcium, d''UVB ou une alimentation inadaptée.','Pyramiding and soft patches often point to a lack of calcium, UVB, or an incorrect diet.'),
(2,'tekst','Hoe vaak moet vers water beschikbaar zijn voor een schildpad?','À quelle fréquence de l''eau fraîche doit-elle être disponible pour une tortue ?','How often should fresh water be available for a tortoise?','["Altijd, dagelijks ververst","Enkel één keer per week","Alleen in de zomer","Schildpadden hebben geen water nodig"]'::jsonb,'["Toujours, renouvelée quotidiennement","Seulement une fois par semaine","Uniquement en été","Les tortues n''ont pas besoin d''eau"]'::jsonb,'["Always, refreshed daily","Only once a week","Only in summer","Tortoises don''t need water"]'::jsonb,0,'Schildpadden drinken en weken regelmatig in water, wat belangrijk is voor hydratatie en spijsvertering.','Les tortues boivent et se trempent régulièrement dans l''eau, important pour l''hydratation et la digestion.','Tortoises drink and soak in water regularly, which is important for hydration and digestion.'),
(3,'tekst','Wat betekent het als een schildpad zich volledig terugtrekt in haar schild bij aanraking?','Que signifie le fait qu''une tortue se rétracte complètement dans sa carapace au contact ?','What does it mean when a tortoise fully retracts into its shell when touched?','["Ze voelt zich bedreigd of gestrest","Ze wil spelen","Ze heeft honger","Het betekent niets speciaals"]'::jsonb,'["Elle se sent menacée ou stressée","Elle veut jouer","Elle a faim","Cela ne signifie rien de particulier"]'::jsonb,'["It feels threatened or stressed","It wants to play","It is hungry","It means nothing in particular"]'::jsonb,0,'Terugtrekken in het schild is een natuurlijk verdedigingsmechanisme tegen gevaar of stress.','Se rétracter dans la carapace est un mécanisme de défense naturel contre le danger ou le stress.','Retracting into the shell is a natural defence mechanism against danger or stress.'),
(3,'tekst','Waarom moet je een schildpad nooit op haar rug leggen of laten liggen?','Pourquoi ne faut-il jamais poser ou laisser une tortue sur le dos ?','Why should you never leave a tortoise on its back?','["Dit kan ademhalingsproblemen en zware stress veroorzaken","Schildpadden vinden dit net leuk","Het heeft geen enkel effect op hen","Ze kunnen zichzelf altijd makkelijk omdraaien"]'::jsonb,'["Cela peut causer des problèmes respiratoires et un stress important","Les tortues aiment bien ça","Cela n''a aucun effet sur elles","Elles peuvent toujours se retourner facilement"]'::jsonb,'["It can cause breathing difficulty and severe stress","Tortoises actually enjoy it","It has no effect on them at all","They can always easily flip themselves back"]'::jsonb,0,'Op de rug liggen kan de organen onder druk zetten en veroorzaakt hevige paniek bij het dier.','Être sur le dos peut comprimer les organes et provoquer une grande panique chez l''animal.','Lying on its back can put pressure on organs and cause severe panic in the animal.'),
(3,'tekst','Hoe til je een schildpad best correct op?','Comment doit-on correctement soulever une tortue ?','How should you correctly pick up a tortoise?','["Met beide handen, laag bij de grond, schild goed ondersteund","Bij één poot optillen","Snel en hoog in de lucht gooien","Aan de staart optillen"]'::jsonb,'["Avec les deux mains, près du sol, carapace bien soutenue","En la soulevant par une seule patte","En la lançant rapidement en l''air","En la soulevant par la queue"]'::jsonb,'["With both hands, low to the ground, shell well supported","By lifting it by one leg","By tossing it quickly in the air","By lifting it by the tail"]'::jsonb,0,'Laag bij de grond optillen vermindert het risico op letsel bij een eventuele val.','Soulever près du sol réduit le risque de blessure en cas de chute.','Lifting low to the ground reduces the risk of injury from a possible fall.'),
(3,'tekst','Waarom moeten kinderen op de kinderboerderij hun handen wassen na contact met een schildpad?','Pourquoi les enfants doivent-ils se laver les mains après avoir touché une tortue à la ferme pédagogique ?','Why should children wash their hands after touching a tortoise at the city farm?','["Om het risico op salmonella-overdracht te verminderen","Omdat schildpadden vies ruiken","Omdat het schild giftig is","Het is niet nodig, schildpadden zijn steriel"]'::jsonb,'["Pour réduire le risque de transmission de la salmonelle","Parce que les tortues sentent mauvais","Parce que la carapace est toxique","Ce n''est pas nécessaire, les tortues sont stériles"]'::jsonb,'["To reduce the risk of salmonella transmission","Because tortoises smell bad","Because the shell is toxic","It''s not needed, tortoises are sterile"]'::jsonb,0,'Reptielen kunnen salmonellabacteriën dragen zonder zelf ziek te zijn, dus handen wassen is een belangrijke hygiëneregel.','Les reptiles peuvent porter la salmonelle sans être malades eux-mêmes, se laver les mains est une règle d''hygiène importante.','Reptiles can carry salmonella bacteria without being sick themselves, so handwashing is an important hygiene rule.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- parkiet: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'parkiet' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Wat is de minimale grootte voor een parkietenkooi voor twee vogels?','Quelle est la taille minimale d''une cage à perruches pour deux oiseaux ?','What is the minimum cage size for two budgerigars?','["30x30x30 cm", "80x40x50 cm of groter", "20x20x20 cm", "De grootte maakt niet uit"]'::jsonb,'["30x30x30 cm", "80x40x50 cm ou plus grand", "20x20x20 cm", "La taille n''a pas d''importance"]'::jsonb,'["30x30x30 cm", "80x40x50 cm or larger", "20x20x20 cm", "Size doesn''t matter"]'::jsonb,1,'Parkieten moeten kunnen vliegen in hun kooi; een kleine kooi leidt tot stress en gedragsproblemen.','Les perruches doivent pouvoir voler dans leur cage ; une cage trop petite cause stress et troubles du comportement.','Budgies need room to fly inside their cage; a small cage causes stress and behavioural problems.'),
  (1,'tekst','Waarom zijn zitstokken van verschillende diktes belangrijk?','Pourquoi des perchoirs de diamètres différents sont-ils importants ?','Why are perches of different diameters important?','["Voor de decoratie", "Om voetproblemen te voorkomen", "Ze zijn niet belangrijk", "Om lawaai te maken"]'::jsonb,'["Pour la décoration", "Pour prévenir les problèmes de pattes", "Ils ne sont pas importants", "Pour faire du bruit"]'::jsonb,'["For decoration", "To prevent foot problems", "They are not important", "To make noise"]'::jsonb,1,'Variatie in stokdikte traint de voetspieren en voorkomt drukplekken en bevangenheid.','La variété de diamètre entraîne les muscles des pattes et évite les points de pression.','Varied perch thickness exercises foot muscles and prevents pressure sores.'),
  (1,'tekst','Hoeveel uur natuurlijk daglicht of volledig spectrum licht heeft een parkiet ongeveer nodig?','De combien d''heures de lumière naturelle une perruche a-t-elle besoin ?','How many hours of natural or full-spectrum light does a budgie need?','["2-4 uur", "10-12 uur", "24 uur ononderbroken", "Licht is niet nodig"]'::jsonb,'["2-4 heures", "10-12 heures", "24 heures sans interruption", "La lumière n''est pas nécessaire"]'::jsonb,'["2-4 hours", "10-12 hours", "24 hours non-stop", "Light is not necessary"]'::jsonb,1,'Een regelmatig dag-nachtritme met voldoende licht is essentieel voor hormonen en welzijn.','Un rythme jour-nuit régulier avec suffisamment de lumière est essentiel pour les hormones et le bien-être.','A regular day-night cycle with enough light is essential for hormones and wellbeing.'),
  (1,'tekst','Waar moet je een parkietenkooi in een Brussels appartement best niet plaatsen?','Où ne faut-il surtout pas placer une cage à perruches dans un appartement bruxellois ?','Where should you avoid placing a budgie cage in a Brussels apartment?','["In een rustige hoek", "Vlak bij het keukenraam", "Vlak naast de kookplaat", "Op ooghoogte"]'::jsonb,'["Dans un coin calme", "Près de la fenêtre de cuisine", "Juste à côté de la plaque de cuisson", "À hauteur des yeux"]'::jsonb,'["In a quiet corner", "Near a kitchen window", "Right next to the stove", "At eye level"]'::jsonb,2,'Dampen van anti-aanbakpannen (PTFE) zijn zeer giftig voor vogels en kunnen dodelijk zijn.','Les vapeurs de poêles antiadhésives (PTFE) sont très toxiques pour les oiseaux et peuvent être mortelles.','Fumes from non-stick pans (PTFE) are highly toxic to birds and can be fatal.'),
  (2,'tekst','Wat is het probleem met een dieet dat enkel uit zaadjes bestaat?','Quel est le problème d''une alimentation composée uniquement de graines ?','What is the problem with a seed-only diet?','["Er is geen probleem", "Het veroorzaakt tekorten aan vitamines en vet zwaarlijvigheid", "Het is te duur", "Zaadjes zijn giftig"]'::jsonb,'["Il n''y a pas de problème", "Cela cause des carences en vitamines et de l''obésité", "C''est trop cher", "Les graines sont toxiques"]'::jsonb,'["There is no problem", "It causes vitamin deficiencies and obesity", "It''s too expensive", "Seeds are toxic"]'::jsonb,1,'Een uitsluitend zaaddieet is vetrijk en arm aan vitamine A, wat leidt tot gezondheidsproblemen.','Une alimentation exclusivement à base de graines est riche en graisses et pauvre en vitamine A, causant des problèmes de santé.','A seed-only diet is high in fat and low in vitamin A, leading to health problems.'),
  (2,'tekst','Welk voedsel is giftig voor parkieten?','Quel aliment est toxique pour les perruches ?','Which food is toxic to budgies?','["Broccoli", "Avocado", "Appel zonder pitjes", "Gekookte wortel"]'::jsonb,'["Le brocoli", "L''avocat", "La pomme sans pépins", "La carotte cuite"]'::jsonb,'["Broccoli", "Avocado", "Apple without seeds", "Cooked carrot"]'::jsonb,1,'Avocado bevat persine, een stof die bij vogels hartproblemen en de dood kan veroorzaken.','L''avocat contient de la persine, une substance qui peut causer des problèmes cardiaques et la mort chez les oiseaux.','Avocado contains persin, a substance that can cause heart problems and death in birds.'),
  (2,'tekst','Hoe vaak moet je vers water en voedsel verversen?','À quelle fréquence faut-il renouveler l''eau et la nourriture fraîches ?','How often should fresh water and food be refreshed?','["Dagelijks", "Om de week", "Om de maand", "Nooit nodig"]'::jsonb,'["Chaque jour", "Une fois par semaine", "Une fois par mois", "Jamais nécessaire"]'::jsonb,'["Daily", "Weekly", "Monthly", "Never needed"]'::jsonb,0,'Dagelijks vers water en voer voorkomt bacteriegroei en houdt de vogel gezond.','De l''eau et de la nourriture fraîches chaque jour évitent la prolifération bactérienne et maintiennent l''oiseau en bonne santé.','Fresh water and food daily prevent bacterial growth and keep the bird healthy.'),
  (2,'tekst','Wat is een teken van ziekte bij een parkiet?','Quel est un signe de maladie chez une perruche ?','What is a sign of illness in a budgie?','["Actief kwetteren", "Opgezette veren en lusteloosheid", "Veel eten", "Regelmatig baden"]'::jsonb,'["Gazouillis actif", "Plumes ébouriffées et léthargie", "Manger beaucoup", "Se baigner régulièrement"]'::jsonb,'["Active chirping", "Fluffed feathers and lethargy", "Eating a lot", "Bathing regularly"]'::jsonb,1,'Vogels verbergen ziekte instinctief; opgezette veren en stilte kunnen wijzen op ernstige problemen.','Les oiseaux cachent instinctivement leur maladie ; des plumes ébouriffées et le silence peuvent indiquer un problème grave.','Birds instinctively hide illness; fluffed feathers and silence can signal serious problems.'),
  (3,'tekst','Hoe herken je stress bij een parkiet?','Comment reconnaît-on le stress chez une perruche ?','How can you recognize stress in a budgie?','["Ze zingt luid", "Veren plukken of bijten", "Ze slaapt overdag", "Ze eet meer dan normaal"]'::jsonb,'["Elle chante fort", "S''arracher les plumes ou mordre", "Elle dort la journée", "Elle mange plus que d''habitude"]'::jsonb,'["It sings loudly", "Feather plucking or biting", "It sleeps during the day", "It eats more than usual"]'::jsonb,1,'Verenplukken is vaak een teken van stress, verveling of een te kleine leefruimte.','L''arrachage de plumes est souvent un signe de stress, d''ennui ou d''un espace de vie trop petit.','Feather plucking is often a sign of stress, boredom, or too small a living space.'),
  (3,'tekst','Waarom hebben parkieten best gezelschap van een soortgenoot?','Pourquoi les perruches ont-elles besoin de la compagnie d''un congénère ?','Why do budgies benefit from having a companion of their own kind?','["Om te vechten", "Het zijn sociale dieren die eenzaamheid slecht verdragen", "Het is niet nodig", "Om meer te eten"]'::jsonb,'["Pour se battre", "Ce sont des animaux sociaux qui supportent mal la solitude", "Ce n''est pas nécessaire", "Pour manger davantage"]'::jsonb,'["To fight", "They are social animals that cope poorly with loneliness", "It''s not necessary", "To eat more"]'::jsonb,1,'Parkieten leven in het wild in groepen; alleen gehouden vogels hebben veel menselijke aandacht nodig.','Dans la nature, les perruches vivent en groupe ; seules, elles ont besoin de beaucoup d''attention humaine.','In the wild budgies live in flocks; kept alone they need a lot of human attention.'),
  (3,'tekst','Hoe train je een parkiet om op je hand te komen zitten?','Comment entraîner une perruche à venir se poser sur la main ?','How do you train a budgie to step onto your hand?','["Door de kooi te schudden", "Met geduld en beloningen zoals millet", "Door de vogel vast te grijpen", "Door te schreeuwen"]'::jsonb,'["En secouant la cage", "Avec patience et récompenses comme le millet", "En attrapant l''oiseau", "En criant"]'::jsonb,'["By shaking the cage", "With patience and rewards like millet", "By grabbing the bird", "By shouting"]'::jsonb,1,'Positieve training met kleine beloningen bouwt vertrouwen op zonder de vogel te stressen.','Un entraînement positif avec de petites récompenses instaure la confiance sans stresser l''oiseau.','Positive training with small rewards builds trust without stressing the bird.'),
  (3,'tekst','Wat moet je doen als je parkiet vrij rondvliegt in de kamer?','Que faut-il faire si votre perruche vole librement dans la pièce ?','What should you do if your budgie flies freely around the room?','["Ramen en spiegels afdekken", "Alle deuren wijd openzetten", "Niets, het is veilig", "De kat erbij laten"]'::jsonb,'["Couvrir fenêtres et miroirs", "Ouvrir grand toutes les portes", "Rien, c''est sans danger", "Laisser le chat s''approcher"]'::jsonb,'["Cover windows and mirrors", "Open all doors wide", "Nothing, it''s safe", "Let the cat come near"]'::jsonb,0,'Vogels herkennen glas niet en kunnen zich ernstig verwonden tegen ramen of spiegels.','Les oiseaux ne reconnaissent pas le verre et peuvent gravement se blesser contre fenêtres ou miroirs.','Birds don''t recognise glass and can seriously injure themselves on windows or mirrors.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- reuzenslak: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'reuzenslak' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Hoe dik moet de bodemlaag minstens zijn zodat een reuzenslak kan ingraven?','Quelle épaisseur minimale doit avoir la couche de fond pour qu''un escargot géant puisse s''enfouir ?','How thick should the substrate layer be at minimum so a giant snail can burrow?',
   '["1 cm volstaat","Minstens 5-8 cm diep, vochtige aarde","Geen substraat nodig","Enkel droog zand"]'::jsonb,
   '["1 cm suffit","Au moins 5-8 cm de terre humide","Pas de substrat nécessaire","Uniquement du sable sec"]'::jsonb,
   '["1 cm is enough","At least 5-8 cm deep, moist soil","No substrate needed","Only dry sand"]'::jsonb,
   1,'Reuzenslakken graven zich in om te rusten en eieren te leggen, daarvoor is diepe, vochtige aarde nodig.','Les escargots géants s''enfouissent pour se reposer et pondre, ce qui nécessite une terre profonde et humide.','Giant snails burrow to rest and lay eggs, which requires deep, moist soil.'),
  (1,'tekst','Welke luchtvochtigheid heeft een reuzenslak nodig in het terrarium?','De quel taux d''humidité un escargot géant a-t-il besoin dans le terrarium ?','What humidity level does a giant snail need in the enclosure?',
   '["Zeer laag, droog klimaat","Hoog, rond 80-90%","Er is geen vochtigheid nodig","Enkel ''s nachts vochtig"]'::jsonb,
   '["Très faible, climat sec","Élevée, autour de 80-90%","Aucune humidité n''est nécessaire","Humide uniquement la nuit"]'::jsonb,
   '["Very low, dry climate","High, around 80-90%","No humidity is needed","Only humid at night"]'::jsonb,
   1,'Een hoge luchtvochtigheid voorkomt uitdroging van de huid en houdt de slak actief en gezond.','Une humidité élevée évite le dessèchement de la peau et maintient l''escargot actif et en bonne santé.','High humidity prevents skin dehydration and keeps the snail active and healthy.'),
  (1,'tekst','Welke temperatuur is ideaal voor een Afrikaanse reuzenslak?','Quelle température est idéale pour un escargot géant africain ?','What temperature is ideal for an African giant snail?',
   '["Rond 10°C","Tussen 23-27°C","Boven 35°C","Onder 5°C"]'::jsonb,
   '["Autour de 10°C","Entre 23-27°C","Au-dessus de 35°C","En dessous de 5°C"]'::jsonb,
   '["Around 10°C","Between 23-27°C","Above 35°C","Below 5°C"]'::jsonb,
   1,'Als tropische soort heeft de reuzenslak een warme omgeving nodig om actief te blijven.','En tant qu''espèce tropicale, l''escargot géant a besoin d''un environnement chaud pour rester actif.','As a tropical species, the giant snail needs a warm environment to stay active.'),
  (1,'tekst','Waarom moet het terrarium goed afgesloten maar toch geventileerd zijn?','Pourquoi le terrarium doit-il être bien fermé mais tout de même ventilé ?','Why should the enclosure be well-sealed yet still ventilated?',
   '["Om ontsnapping te voorkomen en toch luchtcirculatie te behouden","Ventilatie is nooit nodig","Om de slak warmer te maken","Om vocht volledig te blokkeren"]'::jsonb,
   '["Pour éviter l''évasion tout en maintenant une circulation d''air","La ventilation n''est jamais nécessaire","Pour réchauffer l''escargot","Pour bloquer complètement l''humidité"]'::jsonb,
   '["To prevent escape while maintaining air circulation","Ventilation is never necessary","To make the snail warmer","To completely block moisture"]'::jsonb,
   0,'Reuzenslakken kunnen tegen glas omhoog kruipen, dus een gesloten maar geventileerd deksel is nodig.','Les escargots géants peuvent grimper le long du verre, un couvercle fermé mais ventilé est donc nécessaire.','Giant snails can crawl up glass, so a closed but ventilated lid is needed.'),
  (2,'tekst','Welke bron van calcium is essentieel voor een gezonde schelp?','Quelle source de calcium est essentielle pour une coquille saine ?','Which source of calcium is essential for a healthy shell?',
   '["Sepiaschelp of kalkblokjes","Enkel sla","Suikerwater","Zand"]'::jsonb,
   '["Os de seiche ou blocs de calcium","Uniquement de la laitue","Eau sucrée","Sable"]'::jsonb,
   '["Cuttlebone or calcium blocks","Only lettuce","Sugar water","Sand"]'::jsonb,
   0,'Zonder voldoende calcium wordt de schelp broos en kan die zelfs misvormen.','Sans calcium suffisant, la coquille devient fragile et peut même se déformer.','Without enough calcium, the shell becomes brittle and can even deform.'),
  (2,'tekst','Welk soort groenten en fruit is geschikt als hoofdvoeding?','Quel type de légumes et de fruits convient comme alimentation principale ?','What type of vegetables and fruit is suitable as staple food?',
   '["Alleen vlees","Verse sla, komkommer en fruit zoals appel","Chips en brood","Enkel droogvoer voor honden"]'::jsonb,
   '["Uniquement de la viande","Salade fraîche, concombre et fruits comme la pomme","Chips et pain","Uniquement des croquettes pour chiens"]'::jsonb,
   '["Only meat","Fresh lettuce, cucumber and fruit like apple","Chips and bread","Only dog kibble"]'::jsonb,
   1,'Verse groenten en fruit leveren de vezels en vochtigheid die reuzenslakken nodig hebben.','Les légumes et fruits frais apportent les fibres et l''humidité nécessaires aux escargots géants.','Fresh vegetables and fruit provide the fibre and moisture giant snails need.'),
  (2,'tekst','Welk voedsel moet je vermijden voor reuzenslakken?','Quel type de nourriture faut-il éviter pour les escargots géants ?','What kind of food should be avoided for giant snails?',
   '["Zout of bewerkt voedsel","Sla en komkommer","Sepiaschelp","Vochtige aarde"]'::jsonb,
   '["Nourriture salée ou transformée","Salade et concombre","Os de seiche","Terre humide"]'::jsonb,
   '["Salty or processed food","Lettuce and cucumber","Cuttlebone","Moist soil"]'::jsonb,
   0,'Zout is zeer schadelijk en kan zelfs dodelijk zijn voor slakken door uitdroging.','Le sel est très nocif et peut même être mortel pour les escargots par déshydratation.','Salt is very harmful and can even be lethal to snails due to dehydration.'),
  (2,'tekst','Hoe vaak moet het terrarium van een reuzenslak schoongemaakt worden?','À quelle fréquence le terrarium d''un escargot géant doit-il être nettoyé ?','How often should a giant snail enclosure be cleaned?',
   '["Nooit","Wekelijks, om schimmel en bacteriegroei te vermijden","Om de zes maanden","Enkel als het ruikt naar bloemen"]'::jsonb,
   '["Jamais","Chaque semaine, pour éviter moisissures et bactéries","Tous les six mois","Uniquement si cela sent la fleur"]'::jsonb,
   '["Never","Weekly, to avoid mould and bacterial growth","Every six months","Only if it smells like flowers"]'::jsonb,
   1,'Regelmatig schoonmaken houdt de leefomgeving hygiënisch en voorkomt ziektes bij de slak.','Un nettoyage régulier maintient un environnement hygiénique et prévient les maladies chez l''escargot.','Regular cleaning keeps the environment hygienic and prevents illness in the snail.'),
  (3,'tekst','Hoe moet je een reuzenslak correct oppakken?','Comment faut-il soulever correctement un escargot géant ?','How should you correctly pick up a giant snail?',
   '["Aan de schelp trekken","Voorzichtig onder het lichaam ondersteunen","Bij de voelsprieten vastnemen","Snel oppakken zonder waarschuwing"]'::jsonb,
   '["Tirer par la coquille","Soutenir délicatement sous le corps","Le saisir par les antennes","Le saisir rapidement sans prévenir"]'::jsonb,
   '["Pull by the shell","Gently support underneath the body","Grab it by the tentacles","Pick it up quickly without warning"]'::jsonb,
   1,'Voorzichtig ondersteunen voorkomt schade aan de kwetsbare voet en schelp van de slak.','Un soutien délicat évite d''endommager le pied fragile et la coquille de l''escargot.','Gentle support prevents damage to the snail''s vulnerable foot and shell.'),
  (3,'tekst','Waarom moeten handen gewassen worden na contact met een reuzenslak?','Pourquoi faut-il se laver les mains après avoir touché un escargot géant ?','Why should hands be washed after touching a giant snail?',
   '["Om hygiënische redenen, ze kunnen parasieten dragen","Slakkenslijm is giftig voor mensen","Het is niet nodig","Om de geur te verspreiden"]'::jsonb,
   '["Pour des raisons d''hygiène, ils peuvent porter des parasites","Le mucus est toxique pour l''humain","Ce n''est pas nécessaire","Pour répandre l''odeur"]'::jsonb,
   '["For hygiene reasons, they can carry parasites","Snail slime is toxic to humans","It is not necessary","To spread the scent"]'::jsonb,
   0,'Reuzenslakken kunnen drager zijn van parasieten, dus handen wassen is een belangrijke voorzorgsmaatregel.','Les escargots géants peuvent être porteurs de parasites, se laver les mains est donc une précaution importante.','Giant snails can carry parasites, so washing hands is an important precaution.'),
  (3,'tekst','Wat betekent het als een reuzenslak zich terugtrekt in zijn schelp met een vliesje (epifragma)?','Que signifie le fait qu''un escargot géant se retire dans sa coquille avec une membrane (épiphragme) ?','What does it mean when a giant snail withdraws into its shell with a membrane (epiphragm)?',
   '["Hij is ziek en gaat sterven","Hij beschermt zichzelf tegen droogte of kou (rust/aestivatie)","Hij wil spelen","Dit gebeurt nooit bij reuzenslakken"]'::jsonb,
   '["Il est malade et va mourir","Il se protège contre la sécheresse ou le froid (repos/estivation)","Il veut jouer","Cela n''arrive jamais chez les escargots géants"]'::jsonb,
   '["It is sick and will die","It protects itself from dryness or cold (rest/aestivation)","It wants to play","This never happens in giant snails"]'::jsonb,
   1,'Bij ongunstige omstandigheden vormt de slak een beschermend vliesje en gaat hij in rust.','En cas de conditions défavorables, l''escargot forme une membrane protectrice et entre en repos.','Under unfavourable conditions, the snail forms a protective membrane and goes into rest.'),
  (3,'tekst','Waarom is het belangrijk om reuzenslakken niet te lang in de hand te houden?','Pourquoi est-il important de ne pas garder un escargot géant trop longtemps dans la main ?','Why is it important not to hold a giant snail in your hand for too long?',
   '["De warmte en droogte van de hand kunnen hem stress geven","Ze bijten na een tijdje","Ze worden agressief","Er is geen enkel probleem mee"]'::jsonb,
   '["La chaleur et la sécheresse de la main peuvent lui causer du stress","Ils mordent après un moment","Ils deviennent agressifs","Il n''y a aucun problème"]'::jsonb,
   '["The warmth and dryness of the hand can cause it stress","They bite after a while","They become aggressive","There is no issue at all"]'::jsonb,
   0,'Lichaamswarmte en droge huid kunnen de vochtige huid van de slak uitdrogen en stress veroorzaken.','La chaleur corporelle et la peau sèche peuvent dessécher la peau humide de l''escargot et causer du stress.','Body heat and dry skin can dry out the snail''s moist skin and cause stress.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- stadshond: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'stadshond' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Hoeveel wandelingen per dag heeft een gemiddelde stadshond minstens nodig?','De combien de promenades par jour un chien en ville a-t-il besoin au minimum ?','How many walks per day does an average city dog need at minimum?','["1 korte wandeling", "Minstens 2-3 wandelingen", "Enkel in het weekend", "Geen, een tuin volstaat"]'::jsonb,'["1 courte promenade", "Au moins 2-3 promenades", "Seulement le week-end", "Aucune, un jardin suffit"]'::jsonb,'["1 short walk", "At least 2-3 walks", "Only on weekends", "None, a garden is enough"]'::jsonb,1,'Stadshonden zonder tuin hebben meerdere wandelingen per dag nodig voor beweging en behoeftes doen.','Les chiens en ville sans jardin ont besoin de plusieurs sorties par jour pour bouger et faire leurs besoins.','City dogs without a garden need multiple walks a day for exercise and toileting.'),
  (1,'tekst','Waarom kan het asfalt in de zomer gevaarlijk zijn voor een hond?','Pourquoi l''asphalte peut-il être dangereux pour un chien en été ?','Why can asphalt be dangerous for a dog in summer?','["Het is te zacht", "Het kan gloeiend heet worden en pootjes verbranden", "Honden houden er niet van", "Er is geen gevaar"]'::jsonb,'["C''est trop mou", "Il peut devenir brûlant et brûler les coussinets", "Les chiens n''aiment pas ça", "Il n''y a aucun danger"]'::jsonb,'["It''s too soft", "It can become scorching hot and burn paws", "Dogs just dislike it", "There is no danger"]'::jsonb,1,'Test de temperatuur met je hand: als het te heet is voor jou, is het te heet voor de pootjes.','Testez la température avec votre main : si c''est trop chaud pour vous, c''est trop chaud pour les coussinets.','Test the temperature with your hand: if it''s too hot for you, it''s too hot for paws.'),
  (1,'tekst','Hoe kan je stadslawaai en drukte het best introduceren bij een jonge hond?','Comment introduire au mieux le bruit et l''agitation urbaine chez un jeune chien ?','How should you best introduce city noise and bustle to a young dog?','["Direct blootstellen aan drukke pleinen", "Geleidelijk en positief, stap voor stap", "Nooit buiten komen", "Enkel ''s nachts wandelen"]'::jsonb,'["L''exposer directement aux places animées", "Progressivement et positivement, étape par étape", "Ne jamais sortir", "Sortir uniquement la nuit"]'::jsonb,'["Direct exposure to busy squares", "Gradually and positively, step by step", "Never go outside", "Only walk at night"]'::jsonb,1,'Geleidelijke, positieve socialisatie voorkomt angst en overprikkeling door verkeer, mensen en geluiden.','Une socialisation progressive et positive évite la peur et la surstimulation dues au trafic, aux gens et aux bruits.','Gradual, positive socialisation prevents fear and overstimulation from traffic, people and noise.'),
  (1,'tekst','Wat is belangrijk bij het kiezen van een woning voor een hond in de stad?','Qu''est-ce qui est important lors du choix d''un logement pour un chien en ville ?','What matters when choosing housing for a dog in the city?','["Enkel de grootte van de woonkamer", "Toegang tot buitenruimte of nabijgelegen parken", "De kleur van de gordijnen", "Het aantal verdiepingen"]'::jsonb,'["Uniquement la taille du salon", "Accès à un espace extérieur ou des parcs proches", "La couleur des rideaux", "Le nombre d''étages"]'::jsonb,'["Only the size of the living room", "Access to outdoor space or nearby parks", "The colour of the curtains", "The number of floors"]'::jsonb,1,'Toegang tot groene ruimte in de buurt is essentieel voor de mentale en fysieke gezondheid van een hond.','L''accès à des espaces verts à proximité est essentiel pour la santé mentale et physique d''un chien.','Access to nearby green space is essential for a dog''s mental and physical health.'),
  (2,'tekst','Hoeveel keer per dag krijgt een volwassen hond doorgaans te eten?','Combien de fois par jour un chien adulte doit-il généralement manger ?','How many times a day does an adult dog usually eat?','["1-2 keer", "5-6 keer", "Enkel om de twee dagen", "Ononderbroken vrije toegang"]'::jsonb,'["1-2 fois", "5-6 fois", "Seulement tous les deux jours", "Accès libre en continu"]'::jsonb,'["1-2 times", "5-6 times", "Only every other day", "Continuous free access"]'::jsonb,0,'De meeste volwassen honden hebben genoeg aan 1 tot 2 gestructureerde maaltijden per dag.','La plupart des chiens adultes se contentent d''1 à 2 repas structurés par jour.','Most adult dogs do well with 1 to 2 structured meals a day.'),
  (2,'tekst','Wat is een risico van te weinig lichaamsbeweging bij een stadshond?','Quel est un risque lié à un manque d''exercice chez un chien en ville ?','What is a risk of too little exercise for a city dog?','["Betere spijsvertering", "Overgewicht en gedragsproblemen zoals destructief gedrag", "Meer energie", "Geen enkel risico"]'::jsonb,'["Meilleure digestion", "Surpoids et troubles du comportement comme la destruction", "Plus d''énergie", "Aucun risque"]'::jsonb,'["Better digestion", "Obesity and behaviour problems like destructiveness", "More energy", "No risk at all"]'::jsonb,1,'Onvoldoende beweging leidt vaak tot overgewicht en opgekropte energie die zich uit in destructief gedrag.','Un manque d''exercice mène souvent au surpoids et à une énergie accumulée qui se traduit par des comportements destructeurs.','Insufficient exercise often leads to obesity and pent-up energy expressed as destructive behaviour.'),
  (2,'tekst','Waarom is het belangrijk om drinkwater mee te nemen tijdens warme wandelingen?','Pourquoi est-il important d''emporter de l''eau lors des promenades par temps chaud ?','Why is it important to bring drinking water on hot walks?','["Om zelf te drinken", "Om oververhitting en uitdroging bij de hond te voorkomen", "Water is niet nodig buiten", "Om de hond nat te maken voor de lol"]'::jsonb,'["Pour boire soi-même", "Pour éviter la surchauffe et la déshydratation du chien", "L''eau n''est pas nécessaire dehors", "Pour mouiller le chien pour s''amuser"]'::jsonb,'["To drink yourself", "To prevent overheating and dehydration in the dog", "Water isn''t needed outside", "To wet the dog for fun"]'::jsonb,1,'Honden koelen af door hijgen; zonder voldoende water lopen ze risico op hitteberoerte.','Les chiens se refroidissent en haletant ; sans eau suffisante, ils risquent un coup de chaleur.','Dogs cool down by panting; without enough water they risk heatstroke.'),
  (2,'tekst','Wat kan wijzen op stress of een gezondheidsprobleem bij een hond in een druk stadsklimaat?','Qu''est-ce qui peut indiquer du stress ou un problème de santé chez un chien en milieu urbain animé ?','What can indicate stress or a health problem in a dog in a busy urban environment?','["Normale eetlust", "Overmatig hijgen, verminderde eetlust of overdreven blaffen", "Rustig slapen ''s nachts", "Actief spelen met speeltjes"]'::jsonb,'["Appétit normal", "Halètement excessif, perte d''appétit ou aboiements excessifs", "Dormir calmement la nuit", "Jouer activement avec des jouets"]'::jsonb,'["Normal appetite", "Excessive panting, reduced appetite or excessive barking", "Sleeping calmly at night", "Playing actively with toys"]'::jsonb,1,'Verandering in eetlust of gedrag zijn vaak vroege signalen van stress of onderliggende problemen.','Un changement d''appétit ou de comportement est souvent un signal précoce de stress ou de problème sous-jacent.','Changes in appetite or behaviour are often early signals of stress or underlying issues.'),
  (3,'tekst','Hoe reageert een hond het best op drukke voetgangersgebieden?','Comment un chien devrait-il réagir face aux zones piétonnes animées ?','How should a dog ideally react to busy pedestrian areas?','["Met paniek en trekken aan de lijn", "Rustig en aandachtig naar de begeleider, dankzij training", "Door te blaffen naar iedereen", "Door weg te rennen"]'::jsonb,'["Avec panique et en tirant sur la laisse", "Calmement et attentif au maître, grâce à l''entraînement", "En aboyant sur tout le monde", "En s''enfuyant"]'::jsonb,'["With panic and pulling on the leash", "Calmly and attentive to the handler, thanks to training", "By barking at everyone", "By running away"]'::jsonb,1,'Consistente training en socialisatie helpen een hond kalm blijven te midden van stadsdrukte.','Un entraînement et une socialisation cohérents aident le chien à rester calme au milieu de l''agitation urbaine.','Consistent training and socialisation help a dog stay calm amid city bustle.'),
  (3,'tekst','Waarom is het belangrijk je hond aan een vaste dagroutine te laten wennen in de stad?','Pourquoi est-il important d''habituer son chien à une routine quotidienne fixe en ville ?','Why is it important to accustom your dog to a fixed daily routine in the city?','["Het geeft rust en voorspelbaarheid, wat stress vermindert", "Honden hebben geen routine nodig", "Het maakt geen verschil", "Enkel nuttig voor puppy''s"]'::jsonb,'["Cela apporte calme et prévisibilité, réduisant le stress", "Les chiens n''ont pas besoin de routine", "Cela ne change rien", "Utile seulement pour les chiots"]'::jsonb,'["It gives calm and predictability, reducing stress", "Dogs don''t need routine", "It makes no difference", "Only useful for puppies"]'::jsonb,0,'Een voorspelbare routine met wandelingen en maaltijden geeft honden een gevoel van veiligheid in een drukke omgeving.','Une routine prévisible de promenades et repas donne aux chiens un sentiment de sécurité dans un environnement animé.','A predictable routine of walks and meals gives dogs a sense of security in a busy environment.'),
  (3,'tekst','Wat is een goede manier om overprikkeling te voorkomen na een drukke stadswandeling?','Quelle est une bonne façon d''éviter la surstimulation après une promenade urbaine animée ?','What is a good way to prevent overstimulation after a busy city walk?','["Meteen weer naar buiten gaan", "Een rustmoment thuis geven zonder prikkels", "De hond alleen laten in een lawaaierige ruimte", "Extra speeltijd met andere honden direct erna"]'::jsonb,'["Ressortir immédiatement", "Offrir un moment de repos calme à la maison", "Laisser le chien seul dans un espace bruyant", "Du temps de jeu supplémentaire avec d''autres chiens juste après"]'::jsonb,'["Go straight back outside", "Give a calm rest period at home without stimuli", "Leave the dog alone in a noisy space", "Extra playtime with other dogs right after"]'::jsonb,1,'Rust na prikkelrijke ervaringen helpt het zenuwstelsel van de hond te herstellen en voorkomt oververmoeidheid.','Le repos après des expériences stimulantes aide le système nerveux du chien à récupérer et évite l''épuisement.','Rest after stimulating experiences helps the dog''s nervous system recover and prevents overtiredness.'),
  (3,'tekst','Hoe kan je een stadshond het best socialiseren met andere honden?','Comment socialiser au mieux un chien de ville avec d''autres chiens ?','How can you best socialise a city dog with other dogs?','["Via gecontroleerde, positieve ontmoetingen op eigen tempo", "Door hem los te laten bij elke hond die hij tegenkomt", "Door contact met andere honden te vermijden", "Enkel via videobeelden van honden"]'::jsonb,'["Via des rencontres contrôlées et positives à son rythme", "En le laissant en liberté avec chaque chien croisé", "En évitant tout contact avec d''autres chiens", "Uniquement via des vidéos de chiens"]'::jsonb,'["Through controlled, positive encounters at their own pace", "By letting them loose with every dog they meet", "By avoiding contact with other dogs entirely", "Only through videos of dogs"]'::jsonb,0,'Gecontroleerde, positieve ontmoetingen bouwen vertrouwen op en verminderen angst of agressie tegenover andere honden.','Des rencontres contrôlées et positives instaurent la confiance et réduisent la peur ou l''agressivité envers les autres chiens.','Controlled, positive encounters build confidence and reduce fear or aggression toward other dogs.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- vogelspin: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'vogelspin' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Hoeveel bodemsubstraat heeft een vogelspin minimaal nodig om te kunnen graven?','De combien de substrat une mygale a-t-elle besoin au minimum pour pouvoir creuser ?','How much substrate does a tarantula need at minimum to be able to burrow?',
   '["Enkele centimeters","Minstens 10-15 cm diep","Geen substraat nodig","Slechts een dun laagje zand"]'::jsonb,
   '["Quelques centimètres","Au moins 10-15 cm de profondeur","Pas de substrat nécessaire","Une fine couche de sable seulement"]'::jsonb,
   '["A few centimeters","At least 10-15 cm deep","No substrate needed","Just a thin layer of sand"]'::jsonb,
   1,'Veel soorten graven holen; te weinig substraat verhindert natuurlijk gedrag en verhoogt stress.','De nombreuses espèces creusent des terriers ; trop peu de substrat empêche ce comportement naturel et augmente le stress.','Many species burrow; too little substrate prevents natural behaviour and increases stress.'),
  (1,'tekst','Welke luchtvochtigheid hebben de meeste vogelspinsoorten in hun terrarium nodig?','Quel taux d''humidité la plupart des mygales ont-elles besoin dans leur terrarium ?','What humidity level do most tarantula species need in their enclosure?',
   '["Zo droog mogelijk","Afhankelijk van de soort, 60-80%","Altijd 100% vochtig","Vochtigheid speelt geen rol"]'::jsonb,
   '["Le plus sec possible","Selon l''espèce, 60-80%","Toujours 100% d''humidité","L''humidité n''a aucune importance"]'::jsonb,
   '["As dry as possible","Depending on species, 60-80%","Always 100% humidity","Humidity does not matter"]'::jsonb,
   1,'De juiste vochtigheid is essentieel voor een geslaagde vervelling en gezonde ademhaling.','Une humidité adaptée est essentielle pour une mue réussie et une respiration saine.','Correct humidity is essential for a successful moult and healthy breathing.'),
  (1,'tekst','Wat is een belangrijk verschil tussen een boombewonende en een grondbewonende vogelspin qua terrarium?','Quelle est une différence importante entre une mygale arboricole et terricole concernant le terrarium ?','What is an important difference between an arboreal and terrestrial tarantula regarding the enclosure?',
   '["Geen verschil","De boombewonende soort heeft meer hoogte nodig","De grondsoort heeft geen substraat nodig","Boombewonende soorten hebben geen deksel nodig"]'::jsonb,
   '["Aucune différence","L''espèce arboricole a besoin de plus de hauteur","L''espèce terricole n''a pas besoin de substrat","Les espèces arboricoles n''ont pas besoin de couvercle"]'::jsonb,
   '["No difference","The arboreal species needs more vertical space","The terrestrial species needs no substrate","Arboreal species need no lid"]'::jsonb,
   1,'Boombewonende vogelspinnen klimmen graag en hebben verticale ruimte en klimstructuren nodig.','Les mygales arboricoles aiment grimper et ont besoin d''espace vertical et de structures pour grimper.','Arboreal tarantulas like to climb and need vertical space and climbing structures.'),
  (1,'tekst','Waarom is een goed sluitend deksel op het terrarium belangrijk?','Pourquoi un couvercle bien fermé sur le terrarium est-il important ?','Why is a well-fitting lid on the enclosure important?',
   '["Om ontsnapping te voorkomen en veiligheid te garanderen","Puur decoratief","Om het terrarium zwaarder te maken","Vogelspinnen hebben geen deksel nodig"]'::jsonb,
   '["Pour éviter toute évasion et garantir la sécurité","Purement décoratif","Pour alourdir le terrarium","Les mygales n''ont pas besoin de couvercle"]'::jsonb,
   '["To prevent escape and ensure safety","Purely decorative","To make the enclosure heavier","Tarantulas do not need a lid"]'::jsonb,
   0,'Vogelspinnen zijn verrassend behendige klimmers en kunnen via kleine openingen ontsnappen.','Les mygales sont des grimpeuses étonnamment agiles et peuvent s''échapper par de petites ouvertures.','Tarantulas are surprisingly agile climbers and can escape through small gaps.'),
  (2,'tekst','Hoe vaak moet een volwassen vogelspin gemiddeld gevoerd worden?','À quelle fréquence une mygale adulte doit-elle être nourrie en moyenne ?','On average, how often should an adult tarantula be fed?',
   '["Dagelijks","Eén keer per week tot per twee weken","Elke maand slechts één keer per jaar","Nooit, ze eten vanzelf niets"]'::jsonb,
   '["Chaque jour","Une fois par semaine à toutes les deux semaines","Une seule fois par an","Jamais, elles ne mangent pas"]'::jsonb,
   '["Daily","Once a week to once every two weeks","Only once a year","Never, they do not eat"]'::jsonb,
   1,'Vogelspinnen hebben een trage stofwisseling en kunnen weken zonder voedsel overleven.','Les mygales ont un métabolisme lent et peuvent survivre des semaines sans nourriture.','Tarantulas have a slow metabolism and can survive weeks without food.'),
  (2,'tekst','Wat is een teken dat een vogelspin binnenkort gaat vervellen?','Quel est un signe indiquant qu''une mygale va bientôt muer ?','What is a sign that a tarantula is about to moult?',
   '["Ze weigert eten en ligt op haar rug","Ze wordt agressiever dan ooit","Ze verliest kleur volledig","Ze eet plots dubbel zoveel"]'::jsonb,
   '["Elle refuse de manger et se met sur le dos","Elle devient plus agressive que jamais","Elle perd complètement sa couleur","Elle mange soudain deux fois plus"]'::jsonb,
   '["She stops eating and flips onto her back","She becomes more aggressive than ever","She loses all colour","She suddenly eats twice as much"]'::jsonb,
   0,'Voor de vervelling eten vogelspinnen vaak niet meer en trekken ze zich terug.','Avant la mue, les mygales cessent souvent de manger et se retirent.','Before moulting, tarantulas often stop eating and withdraw.'),
  (2,'tekst','Waarom moet er steeds een waterschaaltje aanwezig zijn?','Pourquoi une coupelle d''eau doit-elle toujours être présente ?','Why should a water dish always be present?',
   '["Om te voorkomen dat de spin uitdroogt","Vogelspinnen drinken nooit water","Enkel voor de sier","Om de luchtvochtigheid te verlagen"]'::jsonb,
   '["Pour éviter que la mygale ne se déshydrate","Les mygales ne boivent jamais d''eau","Uniquement pour la décoration","Pour réduire l''humidité"]'::jsonb,
   '["To prevent the spider from dehydrating","Tarantulas never drink water","Purely decorative","To lower humidity"]'::jsonb,
   0,'Ondanks hun beperkte waterbehoefte moeten vogelspinnen steeds toegang hebben tot vers water.','Malgré leurs besoins limités en eau, les mygales doivent toujours avoir accès à de l''eau fraîche.','Despite limited water needs, tarantulas must always have access to fresh water.'),
  (2,'tekst','Wat moet je doen met onaangeraakte prooidieren na een tijdje?','Que faire des proies non consommées après un certain temps ?','What should you do with uneaten prey after a while?',
   '["Ze laten zitten, dat is normaal","Ze verwijderen om stress en verwondingen te vermijden","Meer prooien toevoegen","De spin dwingen te eten"]'::jsonb,
   '["Les laisser, c''est normal","Les retirer pour éviter le stress et les blessures","Ajouter plus de proies","Forcer la mygale à manger"]'::jsonb,
   '["Leave them, it is normal","Remove them to avoid stress and injury","Add more prey","Force the spider to eat"]'::jsonb,
   1,'Levende prooien kunnen een vervellende of rustende vogelspin verwonden als ze te lang blijven.','Les proies vivantes peuvent blesser une mygale en mue ou au repos si elles restent trop longtemps.','Live prey can injure a moulting or resting tarantula if left too long.'),
  (3,'tekst','Waarom is het afgeraden om een vogelspin op te pakken?','Pourquoi est-il déconseillé de manipuler une mygale ?','Why is it discouraged to handle a tarantula?',
   '["Ze zijn giftig voor mensen","Vallen kan haar verwonden en het stresst het dier","Ze houden ervan om gedragen te worden","Het is verplicht volgens de wet"]'::jsonb,
   '["Elles sont venimeuses pour l''humain","Une chute peut la blesser et cela stresse l''animal","Elles adorent être portées","C''est obligatoire par la loi"]'::jsonb,
   '["They are poisonous to humans","A fall can injure her and it stresses the animal","They enjoy being carried","It is legally required"]'::jsonb,
   1,'Een val van zelfs een geringe hoogte kan het achterlijf van een vogelspin fataal beschadigen.','Une chute, même de faible hauteur, peut endommager fatalement l''abdomen d''une mygale.','A fall from even a small height can fatally damage a tarantula''s abdomen.'),
  (3,'tekst','Wat zijn urticerende haren en waarvoor gebruikt de vogelspin ze?','Que sont les poils urticants et à quoi servent-ils à la mygale ?','What are urticating hairs and what does the tarantula use them for?',
   '["Om te horen","Verdediging tegen bedreigingen","Om te ruiken","Om warmte vast te houden"]'::jsonb,
   '["Pour entendre","Défense contre les menaces","Pour sentir","Pour retenir la chaleur"]'::jsonb,
   '["For hearing","Defence against threats","For smelling","For retaining heat"]'::jsonb,
   1,'Sommige Amerikaanse soorten schoppen prikkende haartjes van hun achterlijf als afweer tegen indringers.','Certaines espèces américaines projettent des poils urticants de leur abdomen pour se défendre.','Some American species kick urticating hairs from their abdomen to defend against intruders.'),
  (3,'tekst','Hoe reageert een vogelspin doorgaans op plotse trillingen of licht?','Comment une mygale réagit-elle généralement aux vibrations ou lumières soudaines ?','How does a tarantula typically react to sudden vibrations or light?',
   '["Ze verstijft van blijdschap","Ze schrikt en trekt zich terug of vlucht","Ze komt dichterbij nieuwsgierig","Ze reageert nooit ergens op"]'::jsonb,
   '["Elle se fige de joie","Elle sursaute et se retire ou fuit","Elle s''approche par curiosité","Elle ne réagit jamais à rien"]'::jsonb,
   '["She freezes with joy","She startles and retreats or flees","She curiously approaches","She never reacts to anything"]'::jsonb,
   1,'Vogelspinnen zijn schuwe dieren en trillingen worden vaak als bedreiging ervaren.','Les mygales sont des animaux craintifs et perçoivent souvent les vibrations comme une menace.','Tarantulas are shy animals and often perceive vibrations as a threat.'),
  (3,'tekst','Wat is de beste aanpak bij het bezoeken van vogelspinnen op de kinderboerderij?','Quelle est la meilleure approche lors de la visite des mygales à la ferme pour enfants ?','What is the best approach when visiting tarantulas at the city farm?',
   '["Tikken tegen het glas voor aandacht","Rustig kijken zonder te kloppen of te schudden","Het terrarium openen om te aaien","Luid roepen om reactie uit te lokken"]'::jsonb,
   '["Taper sur la vitre pour attirer l''attention","Observer calmement sans frapper ni secouer","Ouvrir le terrarium pour la caresser","Crier fort pour provoquer une réaction"]'::jsonb,
   '["Tap the glass to get attention","Watch calmly without knocking or shaking","Open the enclosure to pet her","Shout loudly to provoke a reaction"]'::jsonb,
   1,'Rustig observeren respecteert het welzijn van het dier en vermijdt onnodige stress.','Observer calmement respecte le bien-être de l''animal et évite un stress inutile.','Calm observation respects the animal''s welfare and avoids unnecessary stress.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- wandelende-tak: 12 diersoortspecifieke kernvragen
WITH a AS (SELECT id FROM public.academies WHERE slug = 'wandelende-tak' LIMIT 1)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
  (1,'tekst','Hoe hoog moet een terrarium voor wandelende takken minstens zijn?','Quelle doit être la hauteur minimale d''un terrarium pour phasmes ?','How tall should a stick insect enclosure be at minimum?',
   '["Even hoog als breed","Minstens drie keer de lichaamslengte van het dier","Precies 5 cm","Hoogte maakt niet uit"]'::jsonb,
   '["Aussi haut que large","Au moins trois fois la longueur du corps de l''animal","Exactement 5 cm","La hauteur n''a pas d''importance"]'::jsonb,
   '["As tall as it is wide","At least three times the animal''s body length","Exactly 5 cm","Height does not matter"]'::jsonb,
   1,'Voldoende hoogte is nodig zodat het dier zich veilig kan vasthouden tijdens de vervelling.','Une hauteur suffisante est nécessaire pour que l''animal puisse s''accrocher en sécurité pendant la mue.','Sufficient height is needed so the animal can safely hang during moulting.'),
  (1,'tekst','Welke luchtvochtigheid verkiezen de meeste wandelende takken?','Quel taux d''humidité la plupart des phasmes préfèrent-ils ?','What humidity level do most stick insects prefer?',
   '["Zeer droog, woestijnklimaat","Matig tot hoog, regelmatig besproeien","Nooit besproeien","Volledig onder water"]'::jsonb,
   '["Très sec, climat désertique","Modéré à élevé, vaporiser régulièrement","Ne jamais vaporiser","Complètement immergé"]'::jsonb,
   '["Very dry, desert climate","Moderate to high, spray regularly","Never spray","Fully submerged"]'::jsonb,
   1,'Regelmatig besproeien helpt niet alleen de vochtigheid, maar geeft de dieren ook water om te drinken.','Vaporiser régulièrement aide non seulement à l''humidité, mais donne aussi de l''eau à boire aux animaux.','Regular spraying not only helps humidity but also gives the animals water to drink.'),
  (1,'tekst','Wat is essentieel bodemmateriaal onderin het terrarium?','Quel matériau de fond est essentiel au fond du terrarium ?','What is essential substrate material at the bottom of the enclosure?',
   '["Scherp grind","Een zachte laag zoals aarde of vermiculiet","Niets, kale bodem volstaat","Metalen rooster"]'::jsonb,
   '["Gravier tranchant","Une couche souple comme de la terre ou du vermiculite","Rien, un fond nu suffit","Grille métallique"]'::jsonb,
   '["Sharp gravel","A soft layer such as soil or vermiculite","Nothing, a bare floor is fine","Metal grid"]'::jsonb,
   1,'Een zachte bodemlaag vangt vallende dieren op en helpt de vochtigheid te behouden.','Une couche de fond souple amortit la chute des animaux et aide à conserver l''humidité.','A soft substrate layer cushions falling animals and helps retain humidity.'),
  (1,'tekst','Waarom is voldoende ventilatie in het terrarium belangrijk?','Pourquoi une ventilation suffisante dans le terrarium est-elle importante ?','Why is sufficient ventilation in the enclosure important?',
   '["Om schimmel en te veel vocht te voorkomen","Ventilatie is niet nodig","Om het terrarium warmer te maken","Om geluid te dempen"]'::jsonb,
   '["Pour éviter les moisissures et l''excès d''humidité","La ventilation n''est pas nécessaire","Pour réchauffer le terrarium","Pour atténuer le bruit"]'::jsonb,
   '["To prevent mould and excess moisture","Ventilation is not necessary","To make the enclosure warmer","To dampen sound"]'::jsonb,
   0,'Zonder luchtcirculatie kan schimmel ontstaan op de voedselplanten, wat schadelijk is voor de dieren.','Sans circulation d''air, des moisissures peuvent apparaître sur les plantes nourricières, nuisibles aux animaux.','Without air circulation, mould can grow on food plants, which is harmful to the animals.'),
  (2,'tekst','Welke planten worden vaak als voedsel gebruikt voor wandelende takken?','Quelles plantes sont souvent utilisées comme nourriture pour les phasmes ?','Which plants are often used as food for stick insects?',
   '["Rozenblaadjes","Braamblad en klimop, afhankelijk van de soort","Enkel sla","Gras en stro"]'::jsonb,
   '["Pétales de rose","Ronce et lierre, selon l''espèce","Uniquement de la laitue","Herbe et paille"]'::jsonb,
   '["Rose petals","Bramble and ivy, depending on species","Only lettuce","Grass and straw"]'::jsonb,
   1,'Bramble en klimop zijn voor veel soorten geschikte en voedzame waardplanten.','La ronce et le lierre sont des plantes hôtes adaptées et nourrissantes pour de nombreuses espèces.','Bramble and ivy are suitable and nutritious host plants for many species.'),
  (2,'tekst','Hoe vaak moet vers voedsel ververst worden?','À quelle fréquence la nourriture fraîche doit-elle être renouvelée ?','How often should fresh food be replaced?',
   '["Om de maand","Elke twee tot drie dagen, voor het verwelkt","Nooit, verwelkt blad is prima","Elk uur"]'::jsonb,
   '["Une fois par mois","Tous les deux à trois jours, avant qu''elles ne se fanent","Jamais, les feuilles fanées conviennent","Toutes les heures"]'::jsonb,
   '["Once a month","Every two to three days, before it wilts","Never, wilted leaves are fine","Every hour"]'::jsonb,
   1,'Verse bladeren garanderen voldoende vocht en voedingsstoffen voor een gezonde spijsvertering.','Des feuilles fraîches garantissent suffisamment d''humidité et de nutriments pour une bonne digestion.','Fresh leaves ensure enough moisture and nutrients for healthy digestion.'),
  (2,'tekst','Wat kan wijzen op een gezonde vervelling bij een wandelende tak?','Qu''est-ce qui peut indiquer une mue saine chez un phasme ?','What can indicate a healthy moult in a stick insect?',
   '["Het dier verliest een poot en dat is normaal","De oude huid (exuvie) wordt volledig afgeworpen","Het dier stopt met bewegen voorgoed","Het dier verandert nooit van uiterlijk"]'::jsonb,
   '["L''animal perd une patte, c''est normal","La vieille peau (exuvie) est entièrement rejetée","L''animal arrête de bouger définitivement","L''animal ne change jamais d''apparence"]'::jsonb,
   '["The animal loses a leg and that is normal","The old skin (exuvia) is fully shed","The animal stops moving forever","The animal never changes appearance"]'::jsonb,
   1,'Een volledig afgeworpen exuvie wijst op een goed verlopen vervelling zonder complicaties.','Une exuvie entièrement rejetée indique une mue réussie sans complication.','A fully shed exuvia indicates a successful moult without complications.'),
  (2,'tekst','Waarom moet je bladeren wassen voor je ze aan wandelende takken geeft?','Pourquoi faut-il laver les feuilles avant de les donner aux phasmes ?','Why should you wash leaves before giving them to stick insects?',
   '["Om pesticiden en vervuiling te verwijderen","Om de smaak te verbeteren","Wassen is niet nodig","Om de bladeren te verkleuren"]'::jsonb,
   '["Pour éliminer les pesticides et la pollution","Pour améliorer le goût","Le lavage n''est pas nécessaire","Pour changer la couleur des feuilles"]'::jsonb,
   '["To remove pesticides and pollution","To improve the taste","Washing is not necessary","To change the leaf colour"]'::jsonb,
   0,'Pesticiden op bladeren kunnen zeer giftig zijn voor deze gevoelige insecten.','Les pesticides sur les feuilles peuvent être très toxiques pour ces insectes sensibles.','Pesticides on leaves can be highly toxic to these sensitive insects.'),
  (3,'tekst','Hoe gedragen wandelende takken zich meestal als reactie op gevaar?','Comment les phasmes réagissent-ils généralement face au danger ?','How do stick insects typically behave in response to danger?',
   '["Ze vallen stijf naar beneden of blijven roerloos staan (mimicry)","Ze bijten altijd terug","Ze vliegen onmiddellijk weg","Ze maken luid geluid"]'::jsonb,
   '["Ils se laissent tomber raides ou restent immobiles (mimétisme)","Ils mordent toujours en retour","Ils s''envolent immédiatement","Ils émettent un bruit fort"]'::jsonb,
   '["They drop stiffly or freeze motionless (mimicry)","They always bite back","They immediately fly away","They make a loud sound"]'::jsonb,
   0,'Wandelende takken vertrouwen op camouflage en verstijving als voornaamste verdediging tegen roofdieren.','Les phasmes comptent sur le camouflage et l''immobilité comme principale défense contre les prédateurs.','Stick insects rely on camouflage and freezing as their main defence against predators.'),
  (3,'tekst','Is het aangeraden om wandelende takken vaak vast te nemen?','Est-il recommandé de manipuler souvent les phasmes ?','Is it recommended to frequently handle stick insects?',
   '["Ja, dagelijks knuffelen is goed","Neen, beperk hanteren tot wat nodig is om stress te vermijden","Ja, ze houden ervan gedragen te worden","Het maakt niets uit"]'::jsonb,
   '["Oui, les câliner tous les jours est bon","Non, limiter la manipulation au strict nécessaire pour éviter le stress","Oui, ils adorent être portés","Cela n''a pas d''importance"]'::jsonb,
   '["Yes, daily cuddling is good","No, limit handling to what is necessary to avoid stress","Yes, they love being carried","It does not matter"]'::jsonb,
   1,'Fragiele pootjes kunnen makkelijk afbreken bij onvoorzichtig hanteren, dus beperk het tot een minimum.','Les pattes fragiles peuvent facilement se casser lors d''une manipulation imprudente, donc à limiter au minimum.','Fragile legs can easily break with careless handling, so it should be kept to a minimum.'),
  (3,'tekst','Wat moet je doen als je een wandelende tak toch even vastneemt?','Que faire si l''on doit tout de même manipuler un phasme un instant ?','What should you do if you do need to briefly handle a stick insect?',
   '["Aan een poot optillen","Laat het dier zelf op je hand lopen","Vastknijpen om het niet te laten ontsnappen","Aan de voelsprieten trekken"]'::jsonb,
   '["Le soulever par une patte","Laisser l''animal grimper lui-même sur la main","Le serrer pour l''empêcher de s''échapper","Tirer sur les antennes"]'::jsonb,
   '["Lift it by a leg","Let the animal walk onto your hand itself","Squeeze it so it cannot escape","Pull on the antennae"]'::jsonb,
   1,'Door het dier zelf te laten overstappen op je hand voorkom je verwondingen en stress.','En laissant l''animal grimper lui-même sur votre main, vous évitez blessures et stress.','By letting the animal walk onto your hand itself, you avoid injury and stress.'),
  (3,'tekst','Waarom worden veel wandelende takken ''s nachts actiever?','Pourquoi de nombreux phasmes sont-ils plus actifs la nuit ?','Why do many stick insects become more active at night?',
   '["Ze zijn van nature nachtdieren en vermijden zo roofdieren","Ze slapen altijd overdag door verveling","Licht doodt ze","Ze houden niet van warmte"]'::jsonb,
   '["Ils sont naturellement nocturnes et évitent ainsi les prédateurs","Ils dorment toujours le jour par ennui","La lumière les tue","Ils n''aiment pas la chaleur"]'::jsonb,
   '["They are naturally nocturnal and avoid predators this way","They always sleep during the day from boredom","Light kills them","They dislike warmth"]'::jsonb,
   0,'Nachtactiviteit vermindert de kans om overdag door vogels en andere roofdieren opgemerkt te worden.','L''activité nocturne réduit le risque d''être repéré le jour par les oiseaux et autres prédateurs.','Nocturnal activity reduces the chance of being spotted during the day by birds and other predators.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- Kip: inhoudelijk vernieuwde leeftijdsspecifieke bank
-- Academie "kip": volledig herschreven, drietalige vragenpoel.
--
-- Opzet:
--   * doelgroep "kids"  -> korte, concrete vragen (één ronde);
--   * doelgroep "16plus"-> drie rondes die oplopen in diepgang
--                          (module 1 = basis, 2 = dagelijkse zorg, 3 = plicht,
--                           gezondheid en wetgeving);
--   * variant_groep     -> vragen over hetzelfde thema, ook anders verwoord,
--                          kunnen nooit samen in één test terechtkomen;
--   * verplicht         -> essentieel voor dierenwelzijn; komt bij iedereen;
--   * vraag_type getal  -> antwoord is een getal, met een redelijke marge.
--
-- De volgorde van de antwoorden wordt per sessie door elkaar geschud, dus de
-- opgeslagen index zegt niets over wat de deelnemer bovenaan ziet.

delete from academy_vragen
 where academy_id = (select id from academies where slug = 'kip');

insert into academy_vragen (
  academy_id, doelgroep, module, variant_groep, verplicht, moeilijkheid, vraag_type,
  vraag_tekst, vraag_tekst_fr, vraag_tekst_en,
  opties, opties_fr, opties_en, correcte_optie_index,
  correct_getal, getal_marge, getal_eenheid, getal_eenheid_fr, getal_eenheid_en,
  wist_je_dat, wist_je_dat_fr, wist_je_dat_en
)
select
  (select id from academies where slug = 'kip'),
  x.doelgroep, x.module, x.variant_groep, x.verplicht, x.moeilijkheid, x.vraag_type,
  x.nl, x.fr, x.en,
  x.opties_nl, x.opties_fr, x.opties_en, x.correct,
  x.getal, coalesce(x.marge, 0), x.eenheid_nl, x.eenheid_fr, x.eenheid_en,
  x.weetje_nl, x.weetje_fr, x.weetje_en
from jsonb_to_recordset($json$
